export const QUESTIONS = [{"id":1,"prompt":"A compute cluster transfers 1.20 MW to water. With cp = 4.18 kJ/(kg·K) and an allowed 10 K rise, approximately what mass flow is required?","options":[{"id":"1-0","text":"28.7 kg/s","feedback":"1200/(4.18 × 10) = 28.7 kg/s."},{"id":"1-1","text":"14.4 kg/s","feedback":"14.4 kg/s would give about a 20 K rise, above the stated limit."},{"id":"1-2","text":"120 kg/s","feedback":"120 kg/s treats cp as 1 kJ/(kg·K)."},{"id":"1-3","text":"287 kg/s","feedback":"287 kg/s is ten times the required flow."}],"correct":"1-0","hint":"Put heat rate and heat capacity on the same kW/kJ basis.","explanation":"1200/(4.18 × 10) = 28.7 kg/s.","trap":"Do not confuse bulk coolant rise with junction-to-coolant temperature difference.","kind":"calculation","domain":"thermal-fluid"},{"id":2,"prompt":"A cantilever carries a downward end load. Near its fixed wall, which statement about bending is correct?","options":[{"id":"2-0","text":"The top fibers are in tension and the bottom in compression.","feedback":"The downward-loaded cantilever has a hogging bending region near the wall."},{"id":"2-1","text":"The top fibers are in compression and the bottom in tension.","feedback":"That describes the sagging region of a simply supported beam under a downward load."},{"id":"2-2","text":"Both surfaces are in equal axial tension.","feedback":"Pure bending produces tension on one side and compression on the other."},{"id":"2-3","text":"Normal bending stress is largest at the neutral axis.","feedback":"Normal bending stress is zero at the neutral axis in the elementary elastic model."}],"correct":"2-0","hint":"Imagine which side of the bent beam becomes longer.","explanation":"The downward-loaded cantilever has a hogging bending region near the wall.","trap":"The top is not always in compression; determine curvature and boundary conditions.","kind":"reasoning","graph":{"type":"beam","support":"cantilever","uniform":false,"length":null,"at":1,"label":"Downward load"},"domain":"structure"},{"id":3,"prompt":"At fixed liquid flow and fixed Darcy friction factor, the pipe ID rises from 100 to 150 mm. Approximately how do straight-pipe and fitting pressure losses scale if length and fitting K stay fixed?","options":[{"id":"3-0","text":"Straight-pipe loss ×0.132; fitting loss ×0.198.","feedback":"Pipe loss scales as D⁻⁵ and local loss as D⁻⁴: 1/1.5⁵ = 0.132 and 1/1.5⁴ = 0.198."},{"id":"3-1","text":"Both losses ×0.132.","feedback":"D⁻⁵ applies to the straight-pipe term; unchanged fitting K gives D⁻⁴."},{"id":"3-2","text":"Straight-pipe loss ×0.198; fitting loss ×0.132.","feedback":"The exponents are assigned to the wrong terms."},{"id":"3-3","text":"Both losses ×0.444.","feedback":"0.444 is the velocity ratio, not either pressure-loss ratio."}],"correct":"3-0","hint":"Start with velocity proportional to 1/D², then inspect the L/D term.","explanation":"Pipe loss scales as D⁻⁵ and local loss as D⁻⁴: 1/1.5⁵ = 0.132 and 1/1.5⁴ = 0.198.","trap":"Do not apply the straight-pipe scaling to a total that includes fittings.","kind":"calculation","domain":"thermal-fluid"},{"id":4,"prompt":"Your reduced-order tank model matches final pressure but misses early vapor temperature. Which is the strongest next validation step?","options":[{"id":"4-0","text":"Check conservation and compare independent temperature, inventory and vent data.","feedback":"Independent observables and conservation checks can expose compensating errors."},{"id":"4-1","text":"Accept it because final pressure is the main output.","feedback":"One matched observable can hide incorrect heat or mass transfer."},{"id":"4-2","text":"Tune every correlation against the same pressure trace.","feedback":"Fitting one trace repeatedly is calibration, not independent validation."},{"id":"4-3","text":"Replace it with CFD before checking sensors or balances.","feedback":"Additional detail does not remove the need to verify data and conservation."}],"correct":"4-0","hint":"Think about two model errors that could cancel in the pressure trace.","explanation":"Independent observables and conservation checks can expose compensating errors.","trap":"A good answer has personal ownership, a calculation and a validation limit; do not invent metrics.","kind":"reasoning","domain":"thermal-fluid"},{"id":5,"prompt":"A natural-gas feed is 500 tonnes/day and 90% methane by mass. A train recovers 98% of the inlet methane. How much methane component is recovered?","options":[{"id":"5-0","text":"441 tonnes/day","feedback":"500 × 0.90 × 0.98 = 441 tonnes/day of methane."},{"id":"5-1","text":"450 tonnes/day","feedback":"450 tonnes/day is inlet methane before recovery losses."},{"id":"5-2","text":"490 tonnes/day","feedback":"490 tonnes/day applies recovery to total feed without methane fraction."},{"id":"5-3","text":"500 tonnes/day","feedback":"500 tonnes/day ignores composition and recovery losses."}],"correct":"5-0","hint":"Apply composition and component recovery separately.","explanation":"500 × 0.90 × 0.98 = 441 tonnes/day of methane.","trap":"Do not assume LNG and propellant-grade liquid methane are interchangeable.","kind":"calculation","domain":"thermal-fluid"},{"id":6,"prompt":"An 800 W chip has series resistances of 0.005, 0.010 and 0.020 K/W. Local coolant is 30°C. What is its predicted junction temperature?","options":[{"id":"6-0","text":"58°C","feedback":"Rtotal = 0.035 K/W; 30 + 800 × 0.035 = 58°C."},{"id":"6-1","text":"46°C","feedback":"46°C counts only the convection resistance."},{"id":"6-2","text":"35°C","feedback":"35°C confuses the numerical resistance with a temperature rise."},{"id":"6-3","text":"28°C","feedback":"28 K is the rise above coolant, not the absolute junction temperature."}],"correct":"6-0","hint":"Add the series resistances before adding coolant temperature.","explanation":"Rtotal = 0.035 K/W; 30 + 800 × 0.035 = 58°C.","trap":"Increasing flow cannot eliminate interface or conduction resistance.","kind":"calculation","domain":"thermal-fluid"},{"id":7,"prompt":"Pump head is H = 50 − 0.020Q² and system head is H = 10 + 0.030Q², with H in m and Q in m³/h. After a 20% speed increase using affinity scaling of the whole curve, approximately what is the new operating flow?","options":[{"id":"7-0","text":"35.2 m³/h","feedback":"The new pump curve is 72 − 0.020Q²; intersection gives Q = √(62/0.050) = 35.2."},{"id":"7-1","text":"33.9 m³/h","feedback":"33.9 simply multiplies the old operating flow by 1.2 despite static head."},{"id":"7-2","text":"28.3 m³/h","feedback":"28.3 is the original intersection."},{"id":"7-3","text":"40.0 m³/h","feedback":"40.0 does not satisfy the new pump and system equations."}],"correct":"7-0","hint":"Scale the pump curve first; then find its new intersection.","explanation":"The new pump curve is 72 − 0.020Q²; intersection gives Q = √(62/0.050) = 35.2.","trap":"Apply affinity laws to the curve, then find its intersection with the system.","kind":"calculation","graph":{"type":"plot","xLabel":"Flow (m³/h)","yLabel":"Head (m)","xMax":55,"yMax":80,"series":[{"label":"Original pump","kind":"poly","coeff":[50,0,-0.02],"color":"blue","dash":false},{"label":"120% speed","kind":"poly","coeff":[72,0,-0.02],"color":"blue","dash":true},{"label":"System","kind":"poly","coeff":[10,0,0.03],"color":"orange","dash":false}],"revealPoints":[{"x":35.21363372331802,"y":47.2,"label":"New"}]},"domain":"thermal-fluid"},{"id":8,"prompt":"A 12 m steel line cools 180 K. Use constant α = 12×10⁻⁶/K and E = 200 GPa. Which approximate pair gives free movement and fully restrained elastic stress?","options":[{"id":"8-0","text":"25.9 mm contraction; 432 MPa tension.","feedback":"αLΔT gives contraction; preventing contraction creates tensile stress Eα|ΔT|."},{"id":"8-1","text":"25.9 mm contraction; 432 MPa compression.","feedback":"Compression is associated with prevented heating expansion, not prevented contraction."},{"id":"8-2","text":"2.59 mm contraction; 43.2 MPa tension.","feedback":"Both values are a factor of ten too small."},{"id":"8-3","text":"25.9 mm expansion; 432 MPa compression.","feedback":"Cooling gives negative free length change under positive α."}],"correct":"8-0","hint":"Separate the free thermal strain from the mechanical strain needed to prevent it.","explanation":"αLΔT gives contraction; preventing contraction creates tensile stress Eα|ΔT|.","trap":"Cooling under full axial restraint produces tension, not compression.","kind":"calculation","domain":"structure"},{"id":9,"prompt":"A chiller removes 2.0 MW at COP 5. Ignoring other loads, what are compressor input and condenser rejection?","options":[{"id":"9-0","text":"0.40 MW input; 2.40 MW rejection.","feedback":"W = Qcold/COP = 0.40 MW; Qhot = 2.0 + 0.40 = 2.40 MW."},{"id":"9-1","text":"0.40 MW input; 2.00 MW rejection.","feedback":"This omits compressor work from condenser heat."},{"id":"9-2","text":"2.00 MW input; 2.40 MW rejection.","feedback":"COP 5 requires only 0.40 MW input for this duty."},{"id":"9-3","text":"10.0 MW input; 12.0 MW rejection.","feedback":"This multiplies cold duty by COP instead of dividing."}],"correct":"9-0","hint":"The hot side receives both cold-side heat and compressor work.","explanation":"W = Qcold/COP = 0.40 MW; Qhot = 2.0 + 0.40 = 2.40 MW.","trap":"Cooling capacity and electrical input are different; the condenser rejects both.","kind":"calculation","domain":"cycle"},{"id":10,"prompt":"A closed-end thin cylindrical vessel has 0.50 m diameter, 5 mm wall and 20 bar differential pressure. What are the nominal hoop and axial membrane stresses?","options":[{"id":"10-0","text":"100 MPa hoop; 50 MPa axial.","feedback":"Hoop pD/(2t) = 100 MPa; axial pD/(4t) = 50 MPa."},{"id":"10-1","text":"50 MPa hoop; 100 MPa axial.","feedback":"The thin-wall closed-end formulas give hoop stress twice axial stress."},{"id":"10-2","text":"100 MPa hoop; 100 MPa axial.","feedback":"The axial load is distributed over the cylindrical wall and gives half the hoop stress."},{"id":"10-3","text":"10 MPa hoop; 5 MPa axial.","feedback":"The pressure conversion is ten times too small."}],"correct":"10-0","hint":"Use differential pressure in Pa and thickness in metres.","explanation":"Hoop pD/(2t) = 100 MPa; axial pD/(4t) = 50 MPa.","trap":"Use differential pressure and distinguish hoop stress from closed-end axial stress.","kind":"calculation","domain":"structure"},{"id":11,"prompt":"Two parallel branches have ΔP = 2QA² and ΔP = 8QB², with kPa and L/s units. Controlled total flow is 12 L/s. What is the flow split?","options":[{"id":"11-0","text":"A: 8 L/s; B: 4 L/s.","feedback":"Equal branch ΔP gives QA = 2QB; continuity gives 8 and 4."},{"id":"11-1","text":"A: 6 L/s; B: 6 L/s.","feedback":"Equal flow requires equal resistance here, which is not the stated case."},{"id":"11-2","text":"A: 4 L/s; B: 8 L/s.","feedback":"The higher-resistance branch carries the lower flow."},{"id":"11-3","text":"A: 9.6 L/s; B: 2.4 L/s.","feedback":"The flow ratio is the square root of the resistance ratio, not the resistance ratio."}],"correct":"11-0","hint":"Parallel branches share pressure difference, not necessarily flow.","explanation":"Equal branch ΔP gives QA = 2QB; continuity gives 8 and 4.","trap":"Parallel branches have equal pressure difference, not automatically equal flow.","kind":"calculation","domain":"thermal-fluid"},{"id":12,"prompt":"A component has thermal capacitance 12 kJ/K, generates 2.4 kW, and loses all cooling. Neglect heat rejection. It starts at 45°C; shutdown threshold is 65°C. Approximately how long is available?","options":[{"id":"12-0","text":"100 s","feedback":"t = CΔT/Q = 12 × 20/2.4 = 100 s."},{"id":"12-1","text":"10 s","feedback":"10 s is a factor-of-ten error in the stored-energy balance."},{"id":"12-2","text":"40 s","feedback":"40 s would allow only an 8 K rise at 0.20 K/s."},{"id":"12-3","text":"240 s","feedback":"240 s would allow a 48 K rise."}],"correct":"12-0","hint":"First calculate the rate of temperature rise.","explanation":"t = CΔT/Q = 12 × 20/2.4 = 100 s.","trap":"A lumped thermal inventory is only useful if its mass participates on the relevant time scale.","kind":"calculation","domain":"thermal-fluid"},{"id":13,"prompt":"A vented saturated methane tank has 1.5 kW heat leak. Assume all heat vaporizes liquid with hfg = 510 kJ/kg. What is steady boil-off?","options":[{"id":"13-0","text":"10.6 kg/h","feedback":"1.5/510 = 0.00294 kg/s = 10.6 kg/h."},{"id":"13-1","text":"2.94 kg/h","feedback":"2.94 is not the seconds-to-hours conversion of the calculated mass flow."},{"id":"13-2","text":"106 kg/h","feedback":"106 kg/h is ten times the latent-only result."},{"id":"13-3","text":"0.00294 kg/h","feedback":"0.00294 is the value in kg/s, not kg/h."}],"correct":"13-0","hint":"Convert the latent-only result from kg/s to kg/h.","explanation":"1.5/510 = 0.00294 kg/s = 10.6 kg/h.","trap":"Distinguish constant-pressure vented boil-off from sealed-tank pressurization.","kind":"calculation","domain":"thermal-fluid"},{"id":14,"prompt":"An ideal pinned-pinned column has Euler critical load 19.62 kN. Service axial load is 10 kN and required buckling factor is 2.0. Which assessment is correct?","options":[{"id":"14-0","text":"It narrowly fails: allowable load is 9.81 kN.","feedback":"Pcr/2 = 9.81 kN, below 10 kN; actual ideal factor is 1.962."},{"id":"14-1","text":"It passes: 19.62 kN exceeds 10 kN.","feedback":"This checks only factor greater than one, not the required factor of two."},{"id":"14-2","text":"It passes with buckling factor 3.92.","feedback":"3.92 applies the factor twice in the wrong direction."},{"id":"14-3","text":"It fails because the factor is 0.51.","feedback":"10/19.62 = 0.51 is utilization against critical load, not factor of safety."}],"correct":"14-0","hint":"Distinguish critical load from allowable load after the required factor.","explanation":"Pcr/2 = 9.81 kN, below 10 kN; actual ideal factor is 1.962.","trap":"Effective length and weak-axis stiffness matter; axial stress alone can miss failure.","kind":"calculation","domain":"structure"},{"id":15,"prompt":"An ideal counterflow exchanger has hot water 50→40°C and cold water 25→35°C at 500 kW duty. Approximately what UA is required?","options":[{"id":"15-0","text":"33.3 kW/K","feedback":"Both physical-end differences are 15 K, so UA = 500/15 = 33.3 kW/K."},{"id":"15-1","text":"50.0 kW/K","feedback":"10 K is each stream's temperature change, not the LMTD."},{"id":"15-2","text":"20.0 kW/K","feedback":"25 K is not the counterflow LMTD."},{"id":"15-3","text":"The equal terminal differences make UA undefined.","feedback":"Equal differences have a finite limit: LMTD equals that common difference."}],"correct":"15-0","hint":"Pair temperatures at each physical end of the exchanger.","explanation":"Both physical-end differences are 15 K, so UA = 500/15 = 33.3 kW/K.","trap":"A 0/0 expression in the logarithmic formula has a well-defined limit here.","kind":"calculation","domain":"thermal-fluid"},{"id":16,"prompt":"Nitrogen enters an ideal converging nozzle at 10 bar absolute, 300 K. γ = 1.4; backpressure is 1 bar. What happens to ideal mass flow if backpressure falls to 0.5 bar while upstream state and throat area stay fixed?","options":[{"id":"16-0","text":"It remains approximately unchanged because the nozzle is choked.","feedback":"The critical ratio is about 0.528; both backpressure ratios are below it."},{"id":"16-1","text":"It doubles because downstream pressure halves.","feedback":"Once choked, lower backpressure does not double fixed-upstream mass flow."},{"id":"16-2","text":"It halves because downstream density halves.","feedback":"Downstream density alone does not set flow through a sonic throat."},{"id":"16-3","text":"It rises indefinitely as the pressure ratio increases.","feedback":"Sonic choking imposes a limit for the given upstream state and area."}],"correct":"16-0","hint":"Compare backpressure to the critical pressure ratio.","explanation":"The critical ratio is about 0.528; both backpressure ratios are below it.","trap":"Use absolute pressures and distinguish throat state from downstream ambient.","kind":"reasoning","domain":"cycle"},{"id":17,"prompt":"A compute hall releases 5 MW, of which direct liquid cooling captures 90%. What is the appropriate first-pass thermal allocation?","options":[{"id":"17-0","text":"4.5 MW liquid removal and 0.5 MW room-air removal.","feedback":"Ninety percent is 4.5 MW; the residual 0.5 MW still needs a removal path."},{"id":"17-1","text":"5.0 MW liquid removal and no room-air removal.","feedback":"The stated liquid capture fraction is below 100%."},{"id":"17-2","text":"0.5 MW liquid removal and 4.5 MW room-air removal.","feedback":"These fractions are reversed."},{"id":"17-3","text":"4.5 MW total heat rejection including all cooling-machine input.","feedback":"Cooling-machine work can increase ambient rejection above the IT load."}],"correct":"17-0","hint":"Account explicitly for the heat not captured by cold plates.","explanation":"Ninety percent is 4.5 MW; the residual 0.5 MW still needs a removal path.","trap":"A chiller alone is not a cooling system, and liquid cooling need not capture all room heat.","kind":"calculation","domain":"thermal-fluid"},{"id":18,"prompt":"At a claimed steady 1 MW water-cooled load, instruments show 20 kg/s and 30→35°C. With cp = 4.18 kJ/(kg·K), which is the strongest initial response?","options":[{"id":"18-0","text":"The readings imply 418 kW; verify boundaries, sensors, flow and bypasses.","feedback":"20 × 4.18 × 5 = 418 kW; several measurement or boundary explanations remain."},{"id":"18-1","text":"The readings confirm 1 MW; no further check is needed.","feedback":"The heat balance does not match the claimed duty."},{"id":"18-2","text":"The discrepancy proves the pump must be replaced.","feedback":"A larger pump is not justified before identifying the discrepancy."},{"id":"18-3","text":"The discrepancy proves 582 kW is stored indefinitely.","feedback":"Indefinite accumulation is incompatible with the stated steady condition."}],"correct":"18-0","hint":"Compute the measured heat removal before choosing a physical explanation.","explanation":"20 × 4.18 × 5 = 418 kW; several measurement or boundary explanations remain.","trap":"A plausible story is not a diagnosis; propose measurements that separate hypotheses.","kind":"reasoning","domain":"thermal-fluid"},{"id":19,"prompt":"A rigid sealed ideal-gas bottle is at 5 bar gauge, 20°C. Atmospheric pressure is 1 bar. It warms to 60°C at constant mass. Approximately what is final gauge pressure?","options":[{"id":"19-0","text":"5.82 bar gauge","feedback":"Use 6 bar absolute and kelvin: 6 × 333.15/293.15 − 1 = 5.82 bar gauge."},{"id":"19-1","text":"5.68 bar gauge","feedback":"5.68 uses the initial gauge pressure directly in the gas law."},{"id":"19-2","text":"15.0 bar gauge","feedback":"A Celsius temperature ratio is invalid for the ideal-gas relation."},{"id":"19-3","text":"6.82 bar gauge","feedback":"6.82 is the final absolute pressure, before subtracting atmosphere."}],"correct":"19-0","hint":"Convert both pressure and temperature to absolute scales.","explanation":"Use 6 bar absolute and kelvin: 6 × 333.15/293.15 − 1 = 5.82 bar gauge.","trap":"Gas laws require absolute pressure and absolute temperature.","kind":"calculation","domain":"thermal-fluid"},{"id":20,"prompt":"Purified methane enters at 10 t/h and 300 K and leaves as saturated liquid at 112 K. Use gas cp = 2.2 kJ/(kg·K), hfg = 510 kJ/kg, a simplified low-pressure cooling path, and net COP 0.20. Approximately what are cold duty and electrical input?","options":[{"id":"20-0","text":"2.57 MW cold; 12.8 MW electrical.","feedback":"Specific duty is 2.2 × 188 + 510 = 923.6 kJ/kg; use 2.778 kg/s and divide duty by COP."},{"id":"20-1","text":"1.42 MW cold; 7.08 MW electrical.","feedback":"This counts only latent heat and omits cooling the warm gas."},{"id":"20-2","text":"2.57 MW cold; 0.513 MW electrical.","feedback":"Input is cold duty divided by COP, not multiplied."},{"id":"20-3","text":"9.24 MW cold; 46.2 MW electrical.","feedback":"10 t/h must be converted to 2.778 kg/s before multiplying kJ/kg."}],"correct":"20-0","hint":"Include sensible and latent terms, then apply the supplied net COP.","explanation":"Specific duty is 2.2 × 188 + 510 = 923.6 kJ/kg; use 2.778 kg/s and divide duty by COP.","trap":"Cooling duty is not electrical consumption; LNG production is not just latent heat removal.","kind":"calculation","domain":"cycle"},{"id":21,"prompt":"A chilled-pipe jacket is 16°C and the room dew point is 19°C. What should you expect at exposed surfaces?","options":[{"id":"21-0","text":"Condensation where room air reaches the cold surface.","feedback":"A surface below the air's dew point can condense moisture."},{"id":"21-1","text":"No condensation because room dry-bulb is not specified.","feedback":"The supplied dew point and surface temperature already establish the relevant comparison."},{"id":"21-2","text":"Condensation only if the water itself freezes.","feedback":"Condensation does not require freezing."},{"id":"21-3","text":"No condensation as long as coolant pressure is high.","feedback":"Coolant pressure does not set the surrounding air's dew point."}],"correct":"21-0","hint":"Compare the surface temperature with dew point.","explanation":"A surface below the air's dew point can condense moisture.","trap":"Insulation without a continuous vapor barrier can still admit moisture.","kind":"reasoning","domain":"thermal-fluid"},{"id":22,"prompt":"An 8 kN skid's CG is 0.75 m from support A and 1.25 m from B. Support spacing is 2 m. Under gravity alone, what are the vertical reactions?","options":[{"id":"22-0","text":"A: 5 kN; B: 3 kN.","feedback":"Taking moments about A gives RB = 8 × 0.75/2 = 3 kN, leaving 5 kN at A."},{"id":"22-1","text":"A: 4 kN; B: 4 kN.","feedback":"Equal sharing requires the CG at midspan."},{"id":"22-2","text":"A: 3 kN; B: 5 kN.","feedback":"This reverses the moment-based load distribution."},{"id":"22-3","text":"A: 6 kN; B: 2 kN.","feedback":"This pair does not satisfy the stated moment balance."}],"correct":"22-0","hint":"Take moments about one support before summing vertical forces.","explanation":"Taking moments about A gives RB = 8 × 0.75/2 = 3 kN, leaving 5 kN at A.","trap":"Keep each moment lever arm tied to its stated pivot; a gross tipping check is incomplete.","kind":"calculation","domain":"structure"},{"id":23,"prompt":"An open water tank is at 1.00 bar absolute. The pump is 3 m below the surface; suction losses are 0.50 m. Vapor pressure is 0.20 bar absolute. Use ρ = 1000 kg/m³ and g = 9.81 m/s². Approximately what is NPSH available?","options":[{"id":"23-0","text":"10.65 m","feedback":"(100−20) kPa/(ρg) + 3 − 0.5 = 10.65 m."},{"id":"23-1","text":"5.65 m","feedback":"5.65 m is the excess above a hypothetical 5 m requirement, not available NPSH."},{"id":"23-2","text":"2.50 m","feedback":"2.50 m omits the surface-pressure minus vapor-pressure term."},{"id":"23-3","text":"12.69 m","feedback":"12.69 m fails to subtract vapor pressure."}],"correct":"23-0","hint":"Build the suction-side head balance relative to vapor pressure.","explanation":"(100−20) kPa/(ρg) + 3 − 0.5 = 10.65 m.","trap":"Use suction-side absolute pressure and vapor pressure; discharge pressure is not NPSHa.","kind":"calculation","domain":"thermal-fluid"},{"id":24,"prompt":"Assume steady, adiabatic flow with negligible kinetic/potential-energy changes. The throttle has no shaft work; the ideal turbine is reversible. Which statement correctly distinguishes them?","options":[{"id":"24-0","text":"Throttle: approximately constant enthalpy; ideal turbine: constant entropy with enthalpy drop.","feedback":"The throttle energy balance gives h1 ≈ h2; a reversible adiabatic turbine produces work from an enthalpy decrease."},{"id":"24-1","text":"Throttle: constant entropy; ideal turbine: constant enthalpy.","feedback":"The idealizations are reversed."},{"id":"24-2","text":"Both are isenthalpic because both are adiabatic.","feedback":"Adiabatic does not imply no shaft work or constant enthalpy."},{"id":"24-3","text":"Both are isothermal because both reduce pressure.","feedback":"Pressure reduction alone does not establish constant temperature."}],"correct":"24-0","hint":"Write the steady-flow energy equation and identify shaft work.","explanation":"The throttle energy balance gives h1 ≈ h2; a reversible adiabatic turbine produces work from an enthalpy decrease.","trap":"Isenthalpic does not mean isothermal for real fluids; isentropic does not mean constant enthalpy.","kind":"reasoning","domain":"cycle"},{"id":25,"prompt":"A simply supported beam carries a downward midspan load. In its central sagging region, where are compression and tension?","options":[{"id":"25-0","text":"Top in compression; bottom in tension.","feedback":"Sagging curvature shortens the top fibers and lengthens the bottom fibers."},{"id":"25-1","text":"Top in tension; bottom in compression.","feedback":"That is the opposite curvature, as near the wall of a downward-loaded cantilever."},{"id":"25-2","text":"Both top and bottom in compression.","feedback":"Elementary bending produces opposite normal-stress signs across the neutral axis."},{"id":"25-3","text":"Maximum tensile stress at the neutral axis.","feedback":"The elementary normal bending stress is zero at the neutral axis."}],"correct":"25-0","hint":"Sketch the sagging shape and compare top and bottom fiber lengths.","explanation":"Sagging curvature shortens the top fibers and lengthens the bottom fibers.","trap":"There is no universally optimal beam shape independent of loading and constraints.","kind":"reasoning","graph":{"type":"beam","support":"simple","uniform":false,"length":null,"at":0.5,"label":"Downward load"},"domain":"structure"},{"id":26,"prompt":"A counterflow exchanger has inlets 50°C hot and 20°C cold, capacity rates 100 and 50 kW/K, and effectiveness 0.70. It predicts hot outlet 39.5°C and cold outlet 41°C. Which conclusion is correct?","options":[{"id":"26-0","text":"The outlet crossover can be physical because the outlets are at opposite ends.","feedback":"Physical-end differences are 50−41 = 9 K and 39.5−20 = 19.5 K, both positive."},{"id":"26-1","text":"The result violates the second law because the cold outlet exceeds the hot outlet.","feedback":"Comparing outlets at opposite ends does not establish a local crossing."},{"id":"26-2","text":"The result requires heat to flow from colder to warmer fluid locally.","feedback":"Both local terminal driving temperature differences remain positive."},{"id":"26-3","text":"The result proves the exchanger is actually parallel-flow.","feedback":"Counterflow can show outlet crossover; parallel-flow would not achieve this ordering."}],"correct":"26-0","hint":"Pair temperatures that occupy the same physical end.","explanation":"Physical-end differences are 50−41 = 9 K and 39.5−20 = 19.5 K, both positive.","trap":"Counterflow outlet crossover can be physical; a local temperature crossing is different.","kind":"reasoning","domain":"thermal-fluid"},{"id":27,"prompt":"A 4.5 MW load uses chillers rated 1.5 MW each at actual design ambient. Which statement describes four installed chillers?","options":[{"id":"27-0","text":"They provide N+1 capacity, but two unavailable units leave only 3 MW.","feedback":"Three units meet duty and a fourth is the spare; two remaining units give 3 MW."},{"id":"27-1","text":"They provide N+2 capacity and tolerate two outages at full load.","feedback":"Only one installed spare exists beyond the three-unit duty."},{"id":"27-2","text":"They provide 6 MW after any one unit fails.","feedback":"After one failure only three units remain, giving 4.5 MW."},{"id":"27-3","text":"They establish end-to-end redundancy regardless of shared equipment.","feedback":"Common power, controls, piping or heat rejection can still defeat the plant."}],"correct":"27-0","hint":"Determine the duty unit count before adding the spare count.","explanation":"Three units meet duty and a fourth is the spare; two remaining units give 3 MW.","trap":"Spare nameplate capacity is not proof of end-to-end redundancy.","kind":"reasoning","domain":"thermal-fluid"},{"id":28,"prompt":"Gas is 1000 Nm³/h on a defined basis of 1.013 bar absolute and 273.15 K. The line is 8 bar absolute, 300 K. For ideal gas, approximately what actual volume flow enters the pipe?","options":[{"id":"28-0","text":"139 m³/h","feedback":"Vactual = 1000 × (1.013/8) × (300/273.15) ≈ 139 m³/h."},{"id":"28-1","text":"1000 m³/h","feedback":"Normal flow is not actual volume at a different density."},{"id":"28-2","text":"126.6 m³/h","feedback":"126.6 corrects pressure but omits the temperature ratio."},{"id":"28-3","text":"7900 m³/h","feedback":"Higher pressure reduces actual volume for a fixed mass flow."}],"correct":"28-0","hint":"Conserve mass and compare densities through p/T.","explanation":"Vactual = 1000 × (1.013/8) × (300/273.15) ≈ 139 m³/h.","trap":"A standard cubic metre per hour is a mass-flow proxy, not local volumetric flow.","kind":"calculation","domain":"thermal-fluid"},{"id":29,"prompt":"A throttle outlet has h = 110 kJ/kg. At its outlet pressure, hf = 100 and hg = 300 kJ/kg, using a consistent reference. What is equilibrium vapor mass quality?","options":[{"id":"29-0","text":"5%","feedback":"x = (110−100)/(300−100) = 0.05."},{"id":"29-1","text":"50%","feedback":"50% would require h = 200 kJ/kg with these properties."},{"id":"29-2","text":"95%","feedback":"95% would require h = 290 kJ/kg."},{"id":"29-3","text":"A subcooled state with no vapor.","feedback":"The stated enthalpy lies between saturated-liquid and saturated-vapor values."}],"correct":"29-0","hint":"Locate enthalpy within the saturation interval.","explanation":"x = (110−100)/(300−100) = 0.05.","trap":"Negative calculated quality is a signal to change the state model.","kind":"calculation","domain":"thermal-fluid"},{"id":30,"prompt":"In a thermosyphon pressure-building vaporizer, why can increased heater power eventually reduce circulation rather than increase it?","options":[{"id":"30-0","text":"Driving head can saturate while vapor velocity and loop losses keep increasing.","feedback":"The coupled density-head and pressure-loss balance can move to lower flow or lose a steady solution."},{"id":"30-1","text":"Hydrostatic driving head must increase without limit with heater power.","feedback":"The maximum useful density difference is bounded."},{"id":"30-2","text":"Vapor formation eliminates all hydraulic losses.","feedback":"Vapor can greatly increase velocity and friction/acceleration losses."},{"id":"30-3","text":"Steady circulation is fixed by heater power alone.","feedback":"The hydraulic and thermal equations must be solved together."}],"correct":"30-0","hint":"Compare the changes in driving pressure and required pressure.","explanation":"The coupled density-head and pressure-loss balance can move to lower flow or lose a steady solution.","trap":"Heater power and mass flow must be solved together; do not present them as independent knobs.","kind":"reasoning","domain":"thermal-fluid"},{"id":31,"prompt":"Two bolts equally share 12 kN direct shear. Each effective shear area is 50 mm²; supplied allowable shear stress is 100 MPa. Does the elementary direct-shear check pass?","options":[{"id":"31-0","text":"No: each bolt sees 120 MPa.","feedback":"6000 N / 50 mm² = 120 N/mm² = 120 MPa."},{"id":"31-1","text":"Yes: each bolt sees 60 MPa.","feedback":"This divides the load by two twice."},{"id":"31-2","text":"Yes: each bolt sees 12 MPa.","feedback":"This is a factor-of-ten error in force or area."},{"id":"31-3","text":"No: each bolt sees 240 MPa.","feedback":"240 MPa puts the entire 12 kN on each bolt despite equal sharing."}],"correct":"31-0","hint":"Find each bolt force before dividing by effective area.","explanation":"6000 N / 50 mm² = 120 N/mm² = 120 MPa.","trap":"Equal load sharing requires a justified load path and geometry.","kind":"calculation","domain":"structure"},{"id":32,"prompt":"A methane stream has mdot = 5 kg/s, cp = 3.5 kJ/(kg·K), and is initially 4 K subcooled at a specified pressure. A line adds 35 kW. Ignoring pressure loss, what residual subcooling remains?","options":[{"id":"32-0","text":"2 K","feedback":"The heat causes 35/(5×3.5) = 2 K warming, leaving 2 K margin."},{"id":"32-1","text":"4 K","feedback":"This ignores the added heat."},{"id":"32-2","text":"6 K","feedback":"Heat input reduces, rather than increases, subcooling."},{"id":"32-3","text":"No subcooling: exactly saturated.","feedback":"The supplied heat is half the constant-pressure sensible margin."}],"correct":"32-0","hint":"Calculate sensible warming, then subtract it from the inlet margin.","explanation":"The heat causes 35/(5×3.5) = 2 K warming, leaving 2 K margin.","trap":"Subcooling is pressure-dependent; a temperature-only check can miss flashing.","kind":"calculation","domain":"thermal-fluid"},{"id":33,"prompt":"At design duty, a dry cooler can deliver water no colder than 5 K above outdoor dry-bulb. Required supply is 35°C; outdoor dry-bulb is 38°C. Which assessment is correct?","options":[{"id":"33-0","text":"Dry cooling alone cannot meet supply: minimum leaving water is 43°C.","feedback":"38 + 5 = 43°C, above the required supply temperature."},{"id":"33-1","text":"Dry cooling can meet 35°C by increasing flow indefinitely.","feedback":"Flow cannot overcome the passive sink-temperature limit."},{"id":"33-2","text":"Dry cooling must deliver 33°C because it removes 5 K.","feedback":"The approach is above ambient, not subtracted from it."},{"id":"33-3","text":"A passive dry cooler can always cool below ambient.","feedback":"Heat rejection to ambient does not create a sub-ambient source by itself."}],"correct":"33-0","hint":"Treat approach as a limit relative to the heat sink.","explanation":"38 + 5 = 43°C, above the required supply temperature.","trap":"Temperature approach is a constraint; more flow cannot make a passive cooler colder than its sink.","kind":"reasoning","domain":"cycle"},{"id":34,"prompt":"Water flows steadily through a horizontal, constant-ID pipe without leaks or significant density change. Pressure falls downstream due to friction. What happens to mean velocity?","options":[{"id":"34-0","text":"It remains essentially constant.","feedback":"Continuity fixes Vdot/A when area and density are unchanged."},{"id":"34-1","text":"It necessarily rises as pressure falls.","feedback":"That conclusion ignores incompressible continuity in a constant area."},{"id":"34-2","text":"It necessarily falls as pressure falls.","feedback":"A steady pressure gradient can drive the same flow through every section."},{"id":"34-3","text":"It becomes zero once any pressure loss occurs.","feedback":"Friction does not mean flow must stop."}],"correct":"34-0","hint":"Apply mass conservation before a pressure-velocity intuition.","explanation":"Continuity fixes Vdot/A when area and density are unchanged.","trap":"A pressure drop does not automatically imply an increase in liquid velocity.","kind":"reasoning","domain":"thermal-fluid"},{"id":35,"prompt":"For a long isothermal ideal-gas pipeline, neglect acceleration and elevation and use constant Darcy f. Which relation follows from dp/dx = −fρv²/(2D)?","options":[{"id":"35-0","text":"pin² − pout² = fLṁ²RT/(DA²).","feedback":"Substituting ρ = p/(RT) and v = ṁ/(ρA), then integrating p dp, gives the squared-pressure relation."},{"id":"35-1","text":"pin − pout = fLṁ²RT/(DA²).","feedback":"This loses a pressure factor and is dimensionally inconsistent."},{"id":"35-2","text":"pin² − pout² = 2fLṁ²RT/(DA²).","feedback":"The factor 1/2 from integration cancels the original 1/2."},{"id":"35-3","text":"pin² − pout² = fLṁRT/(DA²).","feedback":"The momentum/friction expression depends on mass flow squared."}],"correct":"35-0","hint":"Substitute continuity first, then integrate p dp.","explanation":"Substituting ρ = p/(RT) and v = ṁ/(ρA), then integrating p dp, gives the squared-pressure relation.","trap":"A liquid constant-density DeltaP formula is not automatically valid over a long gas pipeline.","kind":"reasoning","domain":"thermal-fluid"},{"id":36,"prompt":"A 200 kg steel line cools from 293 to 113 K; average cp = 0.50 kJ/(kg·K). If only LOX latent heat of 213 kJ/kg removes this energy, what is the liquid-equivalent consumption?","options":[{"id":"36-0","text":"84.5 kg","feedback":"Metal heat removal is 18,000 kJ; divide by 213 kJ/kg."},{"id":"36-1","text":"42.3 kg","feedback":"This supplies only half the calculated metal cooling energy."},{"id":"36-2","text":"180 kg","feedback":"180 is the temperature change, not a liquid mass."},{"id":"36-3","text":"8.45 kg","feedback":"This is ten times too small."}],"correct":"36-0","hint":"First calculate the metal's energy change; do not start with the latent heat.","explanation":"Metal heat removal is 18,000 kJ; divide by 213 kJ/kg.","trap":"Do not label Q/h_fg an exact chilldown loss or a minimum when other enthalpy changes matter.","kind":"calculation","domain":"thermal-fluid"},{"id":37,"prompt":"Water circulates at 40 L/s against 250 kPa. Pump efficiency is 70%, motor efficiency 95%. Approximately what electrical power is required?","options":[{"id":"37-0","text":"15.0 kW","feedback":"250,000 × 0.040/(0.70×0.95) = 15.0 kW."},{"id":"37-1","text":"10.0 kW","feedback":"10 kW is hydraulic power before losses."},{"id":"37-2","text":"14.3 kW","feedback":"14.3 kW is shaft power before motor losses."},{"id":"37-3","text":"6.65 kW","feedback":"This multiplies hydraulic power by efficiencies rather than dividing."}],"correct":"37-0","hint":"Keep hydraulic, shaft and electrical input as separate quantities.","explanation":"250,000 × 0.040/(0.70×0.95) = 15.0 kW.","trap":"Hydraulic, shaft and electrical power are three different quantities.","kind":"calculation","domain":"thermal-fluid"},{"id":38,"prompt":"For a sphere with radius 10 mm, h = 100 W/(m²·K), and k = 200 W/(m·K), which Biot-number check is appropriate for a lumped model?","options":[{"id":"38-0","text":"Use Lc = V/A = r/3; Bi ≈ 0.00167.","feedback":"For a sphere, V/A = r/3; hLc/k = 0.00167."},{"id":"38-1","text":"Use Lc = r; Bi ≈ 0.005 as the V/A definition.","feedback":"r is not V/A for a sphere."},{"id":"38-2","text":"Use Lc = diameter; Bi ≈ 0.010 as the V/A definition.","feedback":"The diameter is not V/A for the stated lumped check."},{"id":"38-3","text":"Use Lc = 3r; Bi ≈ 0.015 as the V/A definition.","feedback":"3r reverses the geometric factor."}],"correct":"38-0","hint":"Evaluate sphere volume divided by surface area.","explanation":"For a sphere, V/A = r/3; hLc/k = 0.00167.","trap":"For this lumped model use V/A, not automatically the sphere radius.","kind":"calculation","domain":"thermal-fluid"},{"id":39,"prompt":"One pump has H = 40 − 0.010q². The system has H = 0.020Q², with head in m and flow in m³/h. Two identical pumps run in parallel with symmetric sharing. Approximately what total flow follows?","options":[{"id":"39-0","text":"42.2 m³/h","feedback":"Each pump sees Q/2; 40−0.0025Q² = 0.020Q² gives 42.2."},{"id":"39-1","text":"73.0 m³/h","feedback":"73.0 doubles the old flow without increasing system head."},{"id":"39-2","text":"36.5 m³/h","feedback":"36.5 is the one-pump operating flow."},{"id":"39-3","text":"44.7 m³/h","feedback":"44.7 m³/h corresponds to two of these pumps in series, not parallel."}],"correct":"39-0","hint":"Parallel pumps share head, and their flows add.","explanation":"Each pump sees Q/2; 40−0.0025Q² = 0.020Q² gives 42.2.","trap":"Construct the combined curve before finding the new system intersection.","kind":"calculation","graph":{"type":"plot","xLabel":"Flow (m³/h)","yLabel":"Head (m)","xMax":60,"yMax":45,"series":[{"label":"One pump","kind":"poly","coeff":[40,0,-0.01],"color":"blue","dash":false},{"label":"Parallel pair","kind":"poly","coeff":[40,0,-0.0025],"color":"blue","dash":true},{"label":"System","kind":"poly","coeff":[0,0,0.02],"color":"orange","dash":false}]},"domain":"thermal-fluid"},{"id":40,"prompt":"Two brackets have identical geometry and equal elastic modulus, but yield strengths 250 and 500 MPa. Under the same elastic load, how do stress and deflection compare?","options":[{"id":"40-0","text":"Stress and deflection are the same; yield margin differs.","feedback":"Load and geometry set nominal stress, while E and geometry set elastic stiffness."},{"id":"40-1","text":"The stronger bracket has half the stress and half the deflection.","feedback":"Yield strength does not halve either elastic result."},{"id":"40-2","text":"The stronger bracket has the same stress but half the deflection.","feedback":"The elastic modulus and geometry are unchanged."},{"id":"40-3","text":"The stronger bracket has half the stress but the same deflection.","feedback":"The nominal stress is not reduced by raising yield strength."}],"correct":"40-0","hint":"Separate yield resistance from elastic stiffness.","explanation":"Load and geometry set nominal stress, while E and geometry set elastic stiffness.","trap":"Higher yield strength does not imply higher elastic stiffness.","kind":"reasoning","domain":"structure"},{"id":41,"prompt":"A 1 m² gray surface at 300 K has emissivity 0.10 and views a much larger black enclosure at 90 K with view factor 1. With σ = 5.67×10⁻⁸ W/(m²·K⁴), approximately what net radiation leaves it?","options":[{"id":"41-0","text":"45.6 W","feedback":"εσA(300⁴−90⁴) gives 45.6 W."},{"id":"41-1","text":"456 W","feedback":"456 W omits the factor 0.10 emissivity."},{"id":"41-2","text":"11.9 W","feedback":"Radiative exchange requires the fourth power of kelvin temperatures."},{"id":"41-3","text":"1.19 W","feedback":"This does not satisfy the supplied Stefan–Boltzmann expression."}],"correct":"41-0","hint":"Use absolute temperatures to the fourth power.","explanation":"εσA(300⁴−90⁴) gives 45.6 W.","trap":"Radiation uses kelvin to the fourth power and depends on view factors.","kind":"calculation","domain":"thermal-fluid"},{"id":42,"prompt":"A tower rejects 6 MW entirely by evaporation, with hfg = 2400 kJ/kg. Ignore drift. At four cycles of concentration, approximately what are evaporation, blowdown and makeup?","options":[{"id":"42-0","text":"2.50, 0.833 and 3.33 kg/s.","feedback":"E = 6000/2400 = 2.5; B = E/(4−1) = 0.833; M = E+B."},{"id":"42-1","text":"2.50, 0.625 and 3.125 kg/s.","feedback":"B is E/(C−1), not E/C, when drift is neglected."},{"id":"42-2","text":"2.50, 10.0 and 12.5 kg/s.","feedback":"The solids balance does not make blowdown four times evaporation."},{"id":"42-3","text":"3.33, 0.833 and 2.50 kg/s.","feedback":"Makeup must exceed evaporation when there is positive blowdown."}],"correct":"42-0","hint":"Use both total-water and dissolved-solids balances.","explanation":"E = 6000/2400 = 2.5; B = E/(4−1) = 0.833; M = E+B.","trap":"Recirculating tower flow is much larger than makeup; do not equate them.","kind":"calculation","domain":"thermal-fluid"},{"id":43,"prompt":"A liquid-full cryogenic pipe section is isolated between two closed valves and warms. What is the central design concern?","options":[{"id":"43-0","text":"Thermal expansion can overpressure the trapped liquid and requires an engineered relief path.","feedback":"A nearly incompressible trapped liquid cannot freely expand."},{"id":"43-1","text":"Pressure must stay fixed because both valves are closed.","feedback":"Closing valves fixes mass, not pressure."},{"id":"43-2","text":"A check valve automatically provides certified thermal relief.","feedback":"Check valves are not substitutes for a qualified relief arrangement."},{"id":"43-3","text":"A low heat leak cannot cause significant pressure rise.","feedback":"A small expansion in a stiff liquid-full volume can create a large pressure change."}],"correct":"43-0","hint":"Ask where the liquid's free thermal expansion can go.","explanation":"A nearly incompressible trapped liquid cannot freely expand.","trap":"A low heat input can create a high pressure in trapped liquid.","kind":"reasoning","domain":"thermal-fluid"},{"id":44,"prompt":"Flow standard uncertainty is 2%. Two independent temperatures each have 0.10 K standard uncertainty, and measured ΔT is 5 K. Neglect cp uncertainty. Approximately what is the relative standard uncertainty of heat duty?","options":[{"id":"44-0","text":"3.46%","feedback":"uΔT = √(0.1²+0.1²); combine relative temperature and flow terms in quadrature."},{"id":"44-1","text":"2.83%","feedback":"2.83% accounts only for the differential temperature uncertainty."},{"id":"44-2","text":"4.00%","feedback":"4.00% does not match quadrature of the 2.00% flow term and 2.83% differential-temperature term."},{"id":"44-3","text":"6.00%","feedback":"This is not the quadrature result for the supplied uncertainties."}],"correct":"44-0","hint":"Independent uncertainties add as variances, not signed errors.","explanation":"uΔT = √(0.1²+0.1²); combine relative temperature and flow terms in quadrature.","trap":"Small temperature differences can make a heat-balance measurement poorly conditioned.","kind":"calculation","domain":"thermal-fluid"},{"id":45,"prompt":"A water header mixes 8 kg/s returning at 30°C and 2 kg/s bypassing at 20°C. Supply was 20°C. With equal cp, what is mixed return temperature?","options":[{"id":"45-0","text":"28°C","feedback":"Mass-weighted mixing gives (8×30 + 2×20)/10 = 28°C."},{"id":"45-1","text":"25°C","feedback":"25°C weights the unequal mass flows equally."},{"id":"45-2","text":"30°C","feedback":"A cold bypass lowers the mixed temperature below 30°C."},{"id":"45-3","text":"22°C","feedback":"22°C reverses the hot and cold stream weights."}],"correct":"45-0","hint":"Weight each temperature by its mass flow.","explanation":"Mass-weighted mixing gives (8×30 + 2×20)/10 = 28°C.","trap":"A correct total heat balance does not prove good distribution.","kind":"calculation","domain":"thermal-fluid"},{"id":46,"prompt":"For an adiabatic ideal-gas compressor at a specified pressure ratio, isentropic efficiency is below one. How does the actual outlet temperature compare with the isentropic outlet?","options":[{"id":"46-0","text":"Higher, because actual enthalpy rise is larger.","feedback":"Compressor efficiency is Δhs/Δhactual, so inefficiency increases work and temperature rise."},{"id":"46-1","text":"Lower, because inefficiency reduces compression heating.","feedback":"This reverses the compressor efficiency definition."},{"id":"46-2","text":"Equal, because adiabatic always means isentropic.","feedback":"An adiabatic irreversible process generates entropy."},{"id":"46-3","text":"Fixed at inlet temperature, because no heat crosses the wall.","feedback":"No wall heat transfer does not prevent work from raising internal energy."}],"correct":"46-0","hint":"Write the compressor isentropic-efficiency definition.","explanation":"Compressor efficiency is Δhs/Δhactual, so inefficiency increases work and temperature rise.","trap":"For a compressor, inefficiency makes the actual enthalpy rise larger.","kind":"reasoning","domain":"cycle"},{"id":47,"prompt":"A blind flange closes a 100 mm ID pipe at 20 bar gauge pressure. Approximately what axial pressure force acts on the end closure?","options":[{"id":"47-0","text":"15.7 kN","feedback":"F = pA = 2×10⁶ × π(0.1)²/4 = 15.7 kN."},{"id":"47-1","text":"1.57 kN","feedback":"This is a factor-of-ten pressure-conversion error."},{"id":"47-2","text":"157 kN","feedback":"This is ten times the projected-area force."},{"id":"47-3","text":"6.28 kN","feedback":"Pressure force requires projected area, not circumference."}],"correct":"47-0","hint":"Convert bar to Pa and use projected circular area.","explanation":"F = pA = 2×10⁶ × π(0.1)²/4 = 15.7 kN.","trap":"Pressure force acts on projected area; pressure is not a force by itself.","kind":"calculation","domain":"structure"},{"id":48,"prompt":"A liquid-nitrogen test of a future LOX system passes its hydraulic and cold-contraction objectives. Which conclusion is defensible?","options":[{"id":"48-0","text":"Those objectives are supported, but oxygen compatibility and cleanliness still need separate verification.","feedback":"Surrogate tests support their defined objectives; oxygen-service ignition and cleanliness are distinct."},{"id":"48-1","text":"The test proves every valve is oxygen-compatible.","feedback":"A different fluid does not demonstrate oxygen ignition behavior."},{"id":"48-2","text":"The test proves LOX phase behavior will be identical at equal mass flow.","feedback":"Fluid properties and phase conditions differ between nitrogen and oxygen."},{"id":"48-3","text":"The test makes an oxygen-clean handling process unnecessary.","feedback":"Handling and verified cleanliness remain relevant after surrogate testing."}],"correct":"48-0","hint":"Separate a surrogate test objective from final-service qualification.","explanation":"Surrogate tests support their defined objectives; oxygen-service ignition and cleanliness are distinct.","trap":"A surrogate test validates its stated objectives, not every aspect of the final fluid service.","kind":"reasoning","domain":"thermal-fluid"},{"id":49,"prompt":"Under ideal fan affinity scaling at unchanged density and similar efficiency, speed falls to 80%. What are the flow, pressure and power fractions?","options":[{"id":"49-0","text":"0.80 flow; 0.64 pressure; 0.512 power.","feedback":"Similarity gives Q∝N, ΔP∝N² and P∝N³."},{"id":"49-1","text":"0.80 flow; 0.80 pressure; 0.80 power.","feedback":"Pressure and power do not both scale linearly under the supplied model."},{"id":"49-2","text":"0.64 flow; 0.80 pressure; 0.512 power.","feedback":"Flow is linear in speed and pressure is quadratic."},{"id":"49-3","text":"0.80 flow; 0.512 pressure; 0.64 power.","feedback":"The square and cube exponents are reversed."}],"correct":"49-0","hint":"Use the distinct first-, second- and third-power relations.","explanation":"Similarity gives Q∝N, ΔP∝N² and P∝N³.","trap":"Affinity laws describe similar operating conditions; check the actual system.","kind":"calculation","domain":"thermal-fluid"},{"id":50,"prompt":"A portfolio lists a cooling project design basis of 2 MW and about 345 m³/h. What is the most defensible way to discuss it?","options":[{"id":"50-0","text":"Label the design basis, show the supporting calculation, and distinguish it from measured performance.","feedback":"Clear labels make personal contributions and evidence reviewable."},{"id":"50-1","text":"Describe the design capacity as a measured operational result.","feedback":"Design capacity and measured achieved duty are different evidence types."},{"id":"50-2","text":"Claim personal commissioning ownership because you selected components.","feedback":"Sizing work does not establish that you personally commissioned the system."},{"id":"50-3","text":"Present an illustrative recalculation as a historical field measurement.","feedback":"An illustrative hand calculation is not a recorded measurement."}],"correct":"50-0","hint":"Match each claim to the evidence that actually supports it.","explanation":"Clear labels make personal contributions and evidence reviewable.","trap":"A plausible example calculation is useful only when clearly separated from project history.","kind":"reasoning","domain":"thermal-fluid"},{"id":51,"prompt":"A simply supported 3 m beam carries a uniform load of 2 kN/m. What are maximum bending moment and support reactions?","options":[{"id":"51-0","text":"2.25 kN·m; 3 kN at each support.","feedback":"Mmax = wL²/8 = 2.25 kN·m; each reaction is wL/2 = 3 kN."},{"id":"51-1","text":"4.50 kN·m; 3 kN at each support.","feedback":"The moment is twice the correct uniform-load result."},{"id":"51-2","text":"2.25 kN·m; 6 kN at each support.","feedback":"Two 6 kN reactions do not balance the 6 kN total load."},{"id":"51-3","text":"1.50 kN·m; 2 kN at each support.","feedback":"These reactions do not balance the total load and the moment is not wL²/8."}],"correct":"51-0","hint":"Use the uniform-load result, not the midspan point-load result.","explanation":"Mmax = wL²/8 = 2.25 kN·m; each reaction is wL/2 = 3 kN.","trap":"Maximum moment occurs where shear crosses zero for this load case.","kind":"calculation","graph":{"type":"beam","support":"simple","uniform":true,"length":3,"at":0.5,"label":"Uniform load"},"domain":"structure"},{"id":52,"prompt":"For water, use ΔPpsi = (Qgpm/Cv)². A 40 gpm flow passes through a valve. Increasing Cv from 20 to 40 changes fully open pressure loss how?","options":[{"id":"52-0","text":"From 4 psi to 1 psi.","feedback":"(40/20)² = 4; (40/40)² = 1."},{"id":"52-1","text":"From 4 psi to 2 psi.","feedback":"At fixed flow, loss is proportional to 1/Cv² rather than 1/Cv."},{"id":"52-2","text":"From 2 psi to 1 psi.","feedback":"The initial squared ratio is 4, not 2."},{"id":"52-3","text":"From 1 psi to 4 psi.","feedback":"A larger Cv reduces the stated fully open loss."}],"correct":"52-0","hint":"Square the complete flow-to-Cv ratio.","explanation":"(40/20)² = 4; (40/40)² = 1.","trap":"Lower pressure loss and better control are not always the same design objective.","kind":"calculation","domain":"thermal-fluid"},{"id":53,"prompt":"A support conducts between 300 and 90 K. Use k = 15 W/(m·K), area 200 mm² and length 0.20 m. Approximately what is conductive heat leak?","options":[{"id":"53-0","text":"3.15 W","feedback":"Q̇ = kAΔT/L = 15×0.0002×210/0.20 = 3.15 W."},{"id":"53-1","text":"31.5 W","feedback":"This has a factor-of-ten area or length error."},{"id":"53-2","text":"0.315 W","feedback":"This is ten times smaller than the supplied geometry gives."},{"id":"53-3","text":"315 W","feedback":"200 mm² is 0.0002 m², not 0.02 m²."}],"correct":"53-0","hint":"Convert the cross-sectional area before using Fourier's law.","explanation":"Q̇ = kAΔT/L = 15×0.0002×210/0.20 = 3.15 W.","trap":"Mechanical and thermal support design must be evaluated together.","kind":"calculation","domain":"structure"},{"id":54,"prompt":"For a real adiabatic turbine with isentropic efficiency below one, at fixed inlet state and outlet pressure, which trend is expected relative to the isentropic turbine?","options":[{"id":"54-0","text":"Higher outlet enthalpy and less shaft work.","feedback":"ηt = (h1−h2)/(h1−h2s); a smaller actual drop means less work."},{"id":"54-1","text":"Lower outlet enthalpy and more shaft work.","feedback":"That would outperform the reversible adiabatic ideal."},{"id":"54-2","text":"The same outlet enthalpy and less shaft work.","feedback":"With the same inlet, equal outlet enthalpy means equal adiabatic enthalpy-drop work."},{"id":"54-3","text":"Constant outlet temperature equal to inlet temperature.","feedback":"Expansion with work extraction generally changes temperature; adiabatic does not mean isothermal."}],"correct":"54-0","hint":"Contrast turbine and compressor efficiency definitions.","explanation":"ηt = (h1−h2)/(h1−h2s); a smaller actual drop means less work.","trap":"Turbine inefficiency gives less cooling/work than the isentropic ideal.","kind":"reasoning","domain":"cycle"},{"id":55,"prompt":"A model is tuned to one experiment, then predicts a separate dataset without retuning. What is the most accurate description?","options":[{"id":"55-0","text":"The first step is calibration; the second provides independent validation evidence.","feedback":"Separating fitting from evaluation limits circular evidence."},{"id":"55-1","text":"Both steps are independent validation because both use data.","feedback":"Data used for tuning are not independent of that tuning."},{"id":"55-2","text":"The first step proves every closure is physically correct.","feedback":"A fit can conceal compensating errors or nonidentifiable parameters."},{"id":"55-3","text":"The second step is unnecessary once a fit has converged.","feedback":"Prediction outside the fitted record is valuable evidence of generalization."}],"correct":"55-0","hint":"Ask whether the evaluation data affected the tuned parameters.","explanation":"Separating fitting from evaluation limits circular evidence.","trap":"Matching one output does not validate the whole model.","kind":"reasoning","domain":"thermal-fluid"},{"id":56,"prompt":"Wet-bulb is 25°C, tower approach is 4 K, and an intermediate exchanger adds a 3 K cold-end approach. What is the lowest warm-loop supply under those assumptions?","options":[{"id":"56-0","text":"32°C","feedback":"25 + 4 + 3 = 32°C."},{"id":"56-1","text":"29°C","feedback":"29°C is tower leaving water before the exchanger approach."},{"id":"56-2","text":"28°C","feedback":"28°C omits the tower approach."},{"id":"56-3","text":"25°C","feedback":"Neither real device has zero stated approach."}],"correct":"56-0","hint":"Each heat-transfer stage consumes part of the temperature difference.","explanation":"25 + 4 + 3 = 32°C.","trap":"Every heat-transfer stage consumes temperature difference.","kind":"calculation","domain":"thermal-fluid"},{"id":57,"prompt":"For steady radial conduction through cylindrical insulation of length L, inner radius r1 and outer radius r2, which thermal resistance is correct?","options":[{"id":"57-0","text":"ln(r2/r1)/(2πkL).","feedback":"Integrating radial conduction with area 2πrL gives the logarithmic resistance."},{"id":"57-1","text":"(r2−r1)/(kπr1²).","feedback":"This uses axial cross-sectional area for a radial problem."},{"id":"57-2","text":"2πkL/ln(r2/r1).","feedback":"This is conductance, the reciprocal of resistance."},{"id":"57-3","text":"ln(r2/r1)/(2πkL²).","feedback":"Length enters once in the cylindrical area, not squared."}],"correct":"57-0","hint":"The conduction area grows with radius.","explanation":"Integrating radial conduction with area 2πrL gives the logarithmic resistance.","trap":"Use the actual cylindrical area and place thermal resistances correctly.","kind":"reasoning","domain":"thermal-fluid"},{"id":58,"prompt":"A fixed-speed centrifugal pump's discharge valve is slowly closed. Which general statement is defensible without a specific power curve?","options":[{"id":"58-0","text":"Flow moves toward zero and head toward shutoff; shaft-power trend depends on pump design.","feedback":"The system resistance increases; exact power behavior requires the pump's power curve."},{"id":"58-1","text":"Both flow and shaft power must become exactly zero.","feedback":"The impeller can still consume power and heat liquid at zero delivery."},{"id":"58-2","text":"Every centrifugal pump draws its maximum shaft power at shutoff.","feedback":"Different centrifugal-pump types have different power curves."},{"id":"58-3","text":"Suction throttling is equivalent and leaves cavitation margin unchanged.","feedback":"Suction throttling reduces inlet pressure and can worsen cavitation risk."}],"correct":"58-0","hint":"Keep the head curve separate from the power curve.","explanation":"The system resistance increases; exact power behavior requires the pump's power curve.","trap":"Zero delivery does not mean zero heating or zero shaft power.","kind":"reasoning","domain":"thermal-fluid"},{"id":59,"prompt":"A unit recondenses 100 kg/h of vapor at net duty 600 kJ/kg and net COP 0.15. Approximately what cold duty and electrical input are required?","options":[{"id":"59-0","text":"16.7 kW cold; 111 kW electrical.","feedback":"100/3600×600 = 16.7 kW; divide by 0.15 for input."},{"id":"59-1","text":"60.0 kW cold; 400 kW electrical.","feedback":"Hours must be converted to seconds when combining kg/h with kJ/kg."},{"id":"59-2","text":"16.7 kW cold; 2.50 kW electrical.","feedback":"This multiplies by COP rather than dividing."},{"id":"59-3","text":"111 kW cold; 16.7 kW electrical.","feedback":"These values reverse refrigeration duty and required input."}],"correct":"59-0","hint":"Write the mass flow in kg/s before using the net specific duty.","explanation":"100/3600×600 = 16.7 kW; divide by 0.15 for input.","trap":"Keep inventory, energy and operating objectives distinct.","kind":"calculation","domain":"cycle"},{"id":60,"prompt":"You calculate support loads on a pressurized 90° elbow. Which control-volume treatment is necessary?","options":[{"id":"60-0","text":"Include port pressure forces and vector momentum-flux change, then distinguish force on fluid from force on elbow.","feedback":"The wall force follows vector momentum balance; the fluid force on the elbow is its opposite."},{"id":"60-1","text":"Use only momentum flux because port pressure acts internally.","feedback":"Port pressures are external forces on the selected fluid control volume."},{"id":"60-2","text":"Use only pressure forces because momentum is conserved.","feedback":"Conserved momentum requires accounting for its flux change around the bend."},{"id":"60-3","text":"Add pressure as a scalar directly to mass flow.","feedback":"Pressure, mass flow and force have different dimensions."}],"correct":"60-0","hint":"Draw the fluid control volume and label force directions.","explanation":"The wall force follows vector momentum balance; the fluid force on the elbow is its opposite.","trap":"Label whether you are finding force on the fluid, on the pipe, or on the support.","kind":"reasoning","domain":"thermal-fluid"},{"id":61,"prompt":"A 3 MW load runs for 30 s during an interruption. Circulation continues, and a water buffer may warm 5 K. Use cp = 4.18 kJ/(kg·K), ρ = 1000 kg/m³. Approximately what usable buffer volume is required?","options":[{"id":"61-0","text":"4.31 m³","feedback":"E = 3000×30 = 90,000 kJ; V = E/(4.18×5×1000) = 4.31 m³."},{"id":"61-1","text":"0.431 m³","feedback":"This is ten times too little usable thermal storage."},{"id":"61-2","text":"21.5 m³","feedback":"This omits the allowed 5 K temperature rise in the denominator."},{"id":"61-3","text":"0.718 m³","feedback":"This does not absorb the specified 90 MJ under the supplied temperature limit."}],"correct":"61-0","hint":"Use integrated energy, not just the instantaneous heat rate.","explanation":"E = 3000×30 = 90,000 kJ; V = E/(4.18×5×1000) = 4.31 m³.","trap":"Thermal inventory is useful only if it can still be transported to the hot components.","kind":"calculation","domain":"thermal-fluid"},{"id":62,"prompt":"A loop has only 220 kPa available at 30 L/s and needs 1 MW removal. Option A needs 120 kPa and removes 1.1 MW at actual temperatures. B needs 260 kPa and removes 1.5 MW. Which is provisionally compatible with both constraints?","options":[{"id":"62-0","text":"Option A; B fails the available-differential constraint.","feedback":"A satisfies both stated hydraulic and thermal requirements at the specified flow."},{"id":"62-1","text":"Option B; its larger thermal rating compensates for pressure loss.","feedback":"Excess heat-transfer rating cannot supply missing pump head."},{"id":"62-2","text":"Both; the pump pressure is independent of flow.","feedback":"The hydraulic loss must be matched at the required flow."},{"id":"62-3","text":"Neither; capacity must equal exactly 1 MW.","feedback":"A capacity above duty is not inherently incompatible."}],"correct":"62-0","hint":"Check all requirements at one consistent operating point.","explanation":"A satisfies both stated hydraulic and thermal requirements at the specified flow.","trap":"Equipment must satisfy coupled requirements at one consistent operating condition.","kind":"reasoning","domain":"thermal-fluid"},{"id":63,"prompt":"Vapor pressure is 2.0 bar absolute. Recovered pump-inlet pressure is 2.398 bar absolute. A preceding restriction's vena contracta is 0.45 bar lower. Which assessment is correct?","options":[{"id":"63-0","text":"The local minimum is about 1.948 bar, so local vapor formation is a concern.","feedback":"2.398−0.45 = 1.948 bar, below the supplied vapor pressure."},{"id":"63-1","text":"No cavitation is possible because recovered pressure exceeds 2.0 bar.","feedback":"Local pressure can fall below vapor pressure before recovery."},{"id":"63-2","text":"The local minimum is 2.848 bar, so pressure recovery proves no vapor formed.","feedback":"The local depression is subtracted, not added."},{"id":"63-3","text":"Local pressure is irrelevant if discharge pressure is high.","feedback":"Discharge pressure alone does not establish the restriction or suction minimum."}],"correct":"63-0","hint":"Compare the local minimum, not only the recovered reading, with vapor pressure.","explanation":"2.398−0.45 = 1.948 bar, below the supplied vapor pressure.","trap":"Do not double-count the restriction's permanent loss and its additional local pressure depression.","kind":"reasoning","domain":"thermal-fluid"},{"id":64,"prompt":"Identical elastic beams have E = 200 GPa for steel and 70 GPa for aluminium. Ignore self-weight and apply the same load. Approximately how do aluminium and steel deflections compare?","options":[{"id":"64-0","text":"Aluminium deflects 2.86 times as much.","feedback":"For fixed geometry and loading, deflection ∝ 1/E: 200/70 = 2.86."},{"id":"64-1","text":"Aluminium deflects 0.35 times as much.","feedback":"This reverses the modulus ratio."},{"id":"64-2","text":"They deflect equally because geometry is equal.","feedback":"Elastic stiffness depends on E as well as geometry."},{"id":"64-3","text":"Aluminium deflects 7.14 times as much.","feedback":"This is not the given modulus ratio."}],"correct":"64-0","hint":"Compare EI, not density or yield strength.","explanation":"For fixed geometry and loading, deflection ∝ 1/E: 200/70 = 2.86.","trap":"A lighter material may need a larger section to satisfy stiffness.","kind":"calculation","domain":"structure"},{"id":65,"prompt":"Top-fill condensation reduces receiving-tank pressure while warming liquid. Which conclusion follows?","options":[{"id":"65-0","text":"Zero venting need not maximize delivered mass in a volume-limited tank.","feedback":"Condensation heat can warm liquid, reduce its density and alter the filling limit."},{"id":"65-1","text":"Lower vapor pressure proves the liquid must also be colder.","feedback":"Vapor cooling and liquid warming can occur through internal heat exchange."},{"id":"65-2","text":"Condensation removes heat from the entire tank without an energy sink.","feedback":"Heat exchanged between phases remains inside the whole-tank energy balance."},{"id":"65-3","text":"Every top-fill closure can be copied unchanged from LH₂ to LOX.","feedback":"Properties and heat/mass-transfer closures need fluid-specific assessment and validation."}],"correct":"65-0","hint":"Track where heat removed from vapor actually goes.","explanation":"Condensation heat can warm liquid, reduce its density and alter the filling limit.","trap":"Pressure suppression and maximum liquid inventory can be competing objectives.","kind":"reasoning","domain":"thermal-fluid"},{"id":66,"prompt":"For a supplied turbulent model, h∝flow^0.8 and ΔP∝flow² at unchanged efficiency. Doubling flow changes convection coefficient and hydraulic pumping power approximately how?","options":[{"id":"66-0","text":"h ×1.74; power ×8.","feedback":"2^0.8 = 1.74; ΔP×flow scales as flow³, giving 8."},{"id":"66-1","text":"h ×2; power ×2.","feedback":"The supplied exponents are not linear."},{"id":"66-2","text":"h ×1.74; power ×4.","feedback":"×4 is pressure loss; pumping power also includes doubled flow."},{"id":"66-3","text":"h ×4; power ×8.","feedback":"The supplied heat-transfer exponent is 0.8, not 2."}],"correct":"66-0","hint":"Pumping power is pressure difference times volume flow.","explanation":"2^0.8 = 1.74; ΔP×flow scales as flow³, giving 8.","trap":"Evaluate system benefit per pumping cost, not h alone.","kind":"calculation","domain":"thermal-fluid"},{"id":67,"prompt":"A rigid 10 m³ liquid-full water circuit warms 20 K. Use β = 3×10⁻⁴/K and bulk modulus B = 2.2 GPa; neglect pipe compliance. What are free expansion and ideal constrained pressure rise?","options":[{"id":"67-0","text":"60 L; 132 bar.","feedback":"ΔV = βVΔT = 0.060 m³; ΔP ≈ BβΔT = 13.2 MPa = 132 bar."},{"id":"67-1","text":"6 L; 13.2 bar.","feedback":"Both values have a factor-of-ten error."},{"id":"67-2","text":"60 L; 13.2 bar.","feedback":"13.2 MPa is 132 bar, not 13.2 bar."},{"id":"67-3","text":"600 L; 1320 bar.","feedback":"These values are ten times the supplied small-strain estimate."}],"correct":"67-0","hint":"Distinguish MPa from bar after calculating the constrained strain.","explanation":"ΔV = βVΔT = 0.060 m³; ΔP ≈ BβΔT = 13.2 MPa = 132 bar.","trap":"A 60 L thermal expansion does not imply a 60 L nominal expansion vessel.","kind":"calculation","domain":"structure"},{"id":68,"prompt":"Usable methane demand is 1200 t every 48 h. Component recovery is 95% and on-stream availability is 90%. Approximately what on-stream methane feed capacity is required?","options":[{"id":"68-0","text":"29.2 t/h","feedback":"Average useful demand is 25 t/h; divide by both 0.95 and 0.90."},{"id":"68-1","text":"25.0 t/h","feedback":"25 t/h ignores recovery loss and downtime."},{"id":"68-2","text":"26.3 t/h","feedback":"26.3 t/h accounts for recovery but not availability."},{"id":"68-3","text":"21.4 t/h","feedback":"Capacity must exceed, not be below, average usable demand when losses and downtime exist."}],"correct":"68-0","hint":"Separate calendar-average demand from operating-hour capacity.","explanation":"Average useful demand is 25 t/h; divide by both 0.95 and 0.90.","trap":"Distinguish instantaneous transfer capacity, calendar-average production and on-stream capacity.","kind":"calculation","domain":"thermal-fluid"},{"id":69,"prompt":"A reversible refrigerator operates between uniform reservoirs at 280 K and 310 K. What is its Carnot COP?","options":[{"id":"69-0","text":"9.33","feedback":"COPR = Tc/(Th−Tc) = 280/30 = 9.33."},{"id":"69-1","text":"10.33","feedback":"10.33 is the reversible heat-pump COP based on hot-side delivery."},{"id":"69-2","text":"0.0968","feedback":"0.0968 is the reversible engine efficiency, not refrigerator COP."},{"id":"69-3","text":"30.0","feedback":"30 K is the temperature difference, not a COP."}],"correct":"69-0","hint":"Use the cold-side numerator for refrigerator COP.","explanation":"COPR = Tc/(Th−Tc) = 280/30 = 9.33.","trap":"Carnot temperatures are absolute reservoir temperatures, not Celsius values.","kind":"calculation","domain":"cycle"},{"id":70,"prompt":"For an ideal simply supported span under constant load per unit length, the span is halved with section and material unchanged. What happens to maximum bending moment and deflection?","options":[{"id":"70-0","text":"Moment ×1/4; deflection ×1/16.","feedback":"Mmax∝L² and δmax∝L⁴ for the stated uniformly loaded simple span."},{"id":"70-1","text":"Moment ×1/2; deflection ×1/4.","feedback":"These are not the uniform-load exponents."},{"id":"70-2","text":"Moment ×1/4; deflection ×1/4.","feedback":"Deflection depends on the fourth power of span here."},{"id":"70-3","text":"Moment ×1/16; deflection ×1/4.","feedback":"The moment and deflection powers are reversed."}],"correct":"70-0","hint":"Keep load per metre fixed while changing span.","explanation":"Mmax∝L² and δmax∝L⁴ for the stated uniformly loaded simple span.","trap":"A stiffer support arrangement can worsen thermal restraint.","kind":"calculation","domain":"structure"},{"id":71,"prompt":"A sealed gas test shows pressure falling while measured gas temperature also falls. Which conclusion is justified before a real-gas inventory calculation?","options":[{"id":"71-0","text":"Pressure decay alone does not establish leakage.","feedback":"Temperature, real-gas density, sensor response and volume affect the pressure-to-mass inference."},{"id":"71-1","text":"Any pressure decay proves mass was lost.","feedback":"A sealed cooling gas can lose pressure without losing mass."},{"id":"71-2","text":"Constant vessel volume guarantees constant gas temperature.","feedback":"Rigid volume does not prevent energy exchange."},{"id":"71-3","text":"Ideal-gas behavior is exact at 300 bar.","feedback":"High-pressure gas often requires a real-fluid equation of state."}],"correct":"71-0","hint":"Inventory is related to density, not pressure alone.","explanation":"Temperature, real-gas density, sensor response and volume affect the pressure-to-mass inference.","trap":"Pressure decay is not automatically mass loss; high-pressure real-gas effects matter.","kind":"reasoning","domain":"thermal-fluid"},{"id":72,"prompt":"A source is at 6 bar absolute and receiver at 5 bar. Source liquid surface is 2 m higher; density is 450 kg/m³. At a reference flow, losses are 0.80 bar. If receiver pressure rises to 5.5 bar, what changes?","options":[{"id":"72-0","text":"Driving pressure becomes about 0.588 bar, so that same flow is unsupported.","feedback":"Driving pressure is 0.5 bar + ρg×2 ≈ 0.588 bar, below 0.80 bar loss."},{"id":"72-1","text":"Driving pressure becomes about 1.588 bar, so flow necessarily rises.","feedback":"A higher receiver pressure reduces source-to-receiver pressure difference."},{"id":"72-2","text":"Driving pressure remains 1.088 bar because geometry is unchanged.","feedback":"The pressure boundary condition changed even though geometry did not."},{"id":"72-3","text":"The elevation term alone rises by 0.5 bar.","feedback":"The hydrostatic term is unchanged if level and density are unchanged."}],"correct":"72-0","hint":"Add pressure and elevation driving terms, then compare to loss at the same flow.","explanation":"Driving pressure is 0.5 bar + ρg×2 ≈ 0.588 bar, below 0.80 bar loss.","trap":"A larger receiver pressure reduces driving head; define the reference operating condition.","kind":"reasoning","domain":"thermal-fluid"},{"id":73,"prompt":"Which distinction is essential when considering methane-system integration with compute cooling?","options":[{"id":"73-0","text":"Liquefying warm gas consumes refrigeration; warming an available cold stream can absorb heat.","feedback":"The direction of enthalpy flow and the required product state determine whether cold is available for recovery."},{"id":"73-1","text":"Producing LNG creates unlimited free cold for a compute hall.","feedback":"Liquefaction requires enthalpy removal and work; it is not a free-cold generator."},{"id":"73-2","text":"Any launch loading schedule guarantees continuous cooling availability.","feedback":"An intermittent transfer cannot be assumed to support continuous critical load."},{"id":"73-3","text":"A lower methane temperature always means lower total electrical input.","feedback":"Deeper refrigeration generally requires a more demanding temperature lift."}],"correct":"73-0","hint":"Ask whether the methane stream is being cooled or warmed.","explanation":"The direction of enthalpy flow and the required product state determine whether cold is available for recovery.","trap":"Distinguish a refrigeration consumer from an independently available cold stream.","kind":"reasoning","domain":"cycle"},{"id":74,"prompt":"An exchanger has clean U = 2000 W/(m²·K), A = 20 m² and maintained LMTD = 10 K. Added fouling resistance is 0.0002 m²·K/W. Approximately what is fouled duty?","options":[{"id":"74-0","text":"286 kW","feedback":"1/Uf = 1/2000 + 0.0002; Uf ≈ 1429 W/(m²·K), giving 286 kW."},{"id":"74-1","text":"400 kW","feedback":"400 kW is clean duty and ignores the added resistance."},{"id":"74-2","text":"333 kW","feedback":"This does not use the stated total area-based resistance of 0.0007 m²·K/W."},{"id":"74-3","text":"800 kW","feedback":"Adding resistance cannot double heat transfer at fixed LMTD."}],"correct":"74-0","hint":"Add fouling to 1/U rather than directly subtracting it from U.","explanation":"1/Uf = 1/2000 + 0.0002; Uf ≈ 1429 W/(m²·K), giving 286 kW.","trap":"Area-based resistance cannot be added directly to a total K/W resistance without conversion.","kind":"calculation","domain":"thermal-fluid"},{"id":75,"prompt":"A rack-control valve hunts while temperature oscillates. Which first investigation best separates possible causes?","options":[{"id":"75-0","text":"Synchronize valve command/position, temperatures, branch flow and header pressure, then make a bounded step test.","feedback":"Those trends distinguish sensing delay, actuator behavior, hydraulic interactions and control tuning."},{"id":"75-1","text":"Replace the heat exchanger because oscillation uniquely identifies fouling.","feedback":"Several unrelated mechanisms can create similar oscillation."},{"id":"75-2","text":"Increase controller gain repeatedly until oscillation disappears.","feedback":"Higher gain may worsen oscillation; changes need a diagnosed dynamic response."},{"id":"75-3","text":"Assume the pump is undersized without checking measurements.","feedback":"A control symptom is not proof of one hardware cause."}],"correct":"75-0","hint":"Look for the relative timing of command, actual motion, flow and temperature.","explanation":"Those trends distinguish sensing delay, actuator behavior, hydraulic interactions and control tuning.","trap":"Control symptoms can come from mechanics, sensing, hydraulics or tuning.","kind":"reasoning","domain":"thermal-fluid"},{"id":76,"prompt":"A 200 kg package has combined vertical support stiffness 2.0 MN/m. For an undamped single-degree model, approximately what is its natural frequency?","options":[{"id":"76-0","text":"15.9 Hz","feedback":"ωn = √(k/m) = 100 rad/s; fn = ωn/(2π) = 15.9 Hz."},{"id":"76-1","text":"100 Hz","feedback":"100 is angular frequency in rad/s, not frequency in Hz."},{"id":"76-2","text":"1.59 Hz","feedback":"This is ten times below the stated model result."},{"id":"76-3","text":"31.8 Hz","feedback":"This omits the factor 2 in the angular-to-cyclic-frequency conversion."}],"correct":"76-0","hint":"Distinguish radians per second from cycles per second.","explanation":"ωn = √(k/m) = 100 rad/s; fn = ωn/(2π) = 15.9 Hz.","trap":"Natural frequency is not the vibration amplitude, but proximity to excitation is a warning.","kind":"calculation","domain":"structure"},{"id":77,"prompt":"A 1 MW loop permits a 10 K rise. A new coolant has cp = 3.60 kJ/(kg·K) and ρ = 1030 kg/m³. Approximately what volume flow is required?","options":[{"id":"77-0","text":"27.0 L/s","feedback":"ṁ = 1000/(3.6×10) = 27.78 kg/s; divide by 1030 to obtain 27.0 L/s."},{"id":"77-1","text":"23.9 L/s","feedback":"23.9 L/s is the result for water with cp 4.18 and density 1000."},{"id":"77-2","text":"28.6 L/s","feedback":"The supplied density reduces L/s relative to the mass-flow number; it does not increase it."},{"id":"77-3","text":"270 L/s","feedback":"This is a factor-of-ten volume conversion error."}],"correct":"77-0","hint":"Convert thermal mass-flow demand to volume using the new density.","explanation":"ṁ = 1000/(3.6×10) = 27.78 kg/s; divide by 1030 to obtain 27.0 L/s.","trap":"Antifreeze changes both thermal capacity and hydraulics.","kind":"calculation","domain":"thermal-fluid"},{"id":78,"prompt":"A single-phase water line has ρ = 1000 kg/m³, effective wave speed 1000 m/s and velocity 2 m/s. Under ideal rapid closure to zero velocity, approximately what surge does Joukowsky predict?","options":[{"id":"78-0","text":"20 bar above the pre-existing pressure.","feedback":"ΔP = ρaΔv = 2 MPa = 20 bar, a pressure change."},{"id":"78-1","text":"2 bar above the pre-existing pressure.","feedback":"This is ten times below the computed surge."},{"id":"78-2","text":"20 bar as the final absolute pressure regardless of initial state.","feedback":"Joukowsky gives the increment, not a universal final absolute pressure."},{"id":"78-3","text":"Zero pressure rise because final flow is zero.","feedback":"Stopping momentum rapidly can create a large transient pressure."}],"correct":"78-0","hint":"Calculate a pressure increment and keep the initial pressure separate.","explanation":"ΔP = ρaΔv = 2 MPa = 20 bar, a pressure change.","trap":"Steady friction pressure loss does not bound transient pressure.","kind":"calculation","domain":"thermal-fluid"},{"id":79,"prompt":"Room-temperature pipeline methane is sent directly through a pressure-reducing valve. Which statement is most defensible?","options":[{"id":"79-0","text":"Outlet state follows inlet enthalpy and outlet pressure; complete liquefaction cannot be assumed.","feedback":"A real-fluid property calculation is needed; throttling is approximately isenthalpic under the stated usual assumptions."},{"id":"79-1","text":"Any sufficiently large pressure drop guarantees all methane becomes liquid.","feedback":"Phase outcome depends on the enthalpy state, not pressure ratio alone."},{"id":"79-2","text":"A throttle removes arbitrary amounts of enthalpy without another energy path.","feedback":"The standard throttle energy balance does not remove enthalpy."},{"id":"79-3","text":"The valve acts as an isentropic turbine and recovers shaft work.","feedback":"A valve normally dissipates pressure availability without turbine shaft-work recovery."}],"correct":"79-0","hint":"Locate the inlet enthalpy at the downstream pressure.","explanation":"A real-fluid property calculation is needed; throttling is approximately isenthalpic under the stated usual assumptions.","trap":"Joule-Thomson cooling and complete liquefaction are different outcomes.","kind":"reasoning","domain":"cycle"},{"id":80,"prompt":"A completely filled closed water loop rises 30 m and returns to the pump. Total friction/component loss at design flow is 80 kPa; it remains single phase. What pump differential is needed for steady circulation?","options":[{"id":"80-0","text":"80 kPa; net loop elevation change is zero.","feedback":"Elevation cancels around the complete filled loop, leaving the stated hydraulic losses."},{"id":"80-1","text":"About 374 kPa; always add 30 m of static head.","feedback":"The full up-and-down closed path does not have a net 30 m elevation rise."},{"id":"80-2","text":"About 294 kPa; ignore friction and add elevation only.","feedback":"The pump must still supply dissipative losses."},{"id":"80-3","text":"Zero; gravity cancels every loss in a closed loop.","feedback":"Gravity cancellation does not cancel frictional dissipation."}],"correct":"80-0","hint":"Trace a complete circuit back to the same elevation.","explanation":"Elevation cancels around the complete filled loop, leaving the stated hydraulic losses.","trap":"Closed-loop static pressure and required circulating pump differential are different.","kind":"reasoning","domain":"thermal-fluid"},{"id":81,"prompt":"A cryogenic valve body is stainless steel. What can be concluded about suitability for LOX?","options":[{"id":"81-0","text":"The complete valve still needs oxygen compatibility and cleanliness assessment.","feedback":"The full configuration, nonmetals, contaminants and ignition mechanisms matter."},{"id":"81-1","text":"Its metal name alone proves all seals and lubricants are compatible.","feedback":"The body material says nothing conclusive about every other component."},{"id":"81-2","text":"Any stainless valve is automatically qualified at all pressures and velocities.","feedback":"Service state and configuration influence oxygen hazards."},{"id":"81-3","text":"Cold mechanical strength eliminates oxygen ignition mechanisms.","feedback":"Mechanical strength and ignition compatibility address different failure mechanisms."}],"correct":"81-0","hint":"Treat the valve as an assembly, not just one metal.","explanation":"The full configuration, nonmetals, contaminants and ignition mechanisms matter.","trap":"Cryogenic mechanical suitability and oxygen ignition compatibility are distinct checks.","kind":"reasoning","domain":"structure"},{"id":82,"prompt":"Water has ρ = 1000 kg/m³ and μ = 0.001 Pa·s. It flows at 0.010 L/s through a 10 mm ID pipe. Approximately what is Reynolds number and the defensible regime assessment?","options":[{"id":"82-0","text":"Re ≈ 1270; laminar is a reasonable first estimate.","feedback":"V̇ = 10⁻⁵ m³/s; v≈0.127 m/s and Re≈1273."},{"id":"82-1","text":"Re ≈ 12,700; clearly turbulent.","feedback":"This uses ten times the supplied flow."},{"id":"82-2","text":"Re ≈ 127; velocity must be neglected.","feedback":"This is ten times below the continuity-based result."},{"id":"82-3","text":"Re ≈ 1270; fully turbulent by definition.","feedback":"1270 is below the usual round-pipe transition range."}],"correct":"82-0","hint":"Convert L/s to m³/s before calculating velocity.","explanation":"V̇ = 10⁻⁵ m³/s; v≈0.127 m/s and Re≈1273.","trap":"The requested scaling can violate the regime assumption after the change.","kind":"calculation","domain":"thermal-fluid"},{"id":83,"prompt":"A compressor uses 4 MW shaft input. Gas gains 3.6 MW enthalpy and jacket cooling removes 0.4 MW. A downstream cooler removes 3.0 MW. What total cooling-water load and net retained gas enthalpy rise follow?","options":[{"id":"83-0","text":"3.4 MW water load; 0.6 MW retained by gas.","feedback":"Water gets 0.4+3.0=3.4 MW; gas retains 3.6−3.0=0.6 MW."},{"id":"83-1","text":"7.4 MW water load; 0.6 MW retained by gas.","feedback":"Adding shaft input again double-counts energy already assigned to gas and jacket."},{"id":"83-2","text":"3.0 MW water load; 1.0 MW retained by gas.","feedback":"This omits the jacket path from the water boundary."},{"id":"83-3","text":"4.0 MW water load; zero retained by gas.","feedback":"The supplied aftercooling leaves gas enthalpy 0.6 MW above inlet."}],"correct":"83-0","hint":"Draw a boundary around both compressor and downstream cooler.","explanation":"Water gets 0.4+3.0=3.4 MW; gas retains 3.6−3.0=0.6 MW.","trap":"Draw one consistent control volume before adding equipment loads.","kind":"calculation","domain":"cycle"},{"id":84,"prompt":"A steel rod is fixed against axial expansion and warms 50 K. Use E = 200 GPa and α = 12×10⁻⁶/K. What ideal elastic thermal stress is generated?","options":[{"id":"84-0","text":"120 MPa compression.","feedback":"Preventing αΔT expansion requires compressive mechanical strain: EαΔT = 120 MPa."},{"id":"84-1","text":"120 MPa tension.","feedback":"Tension is associated with preventing cooling contraction."},{"id":"84-2","text":"12 MPa compression.","feedback":"This is a factor-of-ten strain error."},{"id":"84-3","text":"Zero, because there is no applied mechanical force.","feedback":"The restraints supply reaction forces even without a separately applied axial load."}],"correct":"84-0","hint":"Determine the strain the restraints must impose against free expansion.","explanation":"Preventing αΔT expansion requires compressive mechanical strain: EαΔT = 120 MPa.","trap":"Restrained heating produces compression; temperature change alone does not always produce stress.","kind":"calculation","domain":"structure"},{"id":85,"prompt":"A cooling plant has an installed spare pump. Which test most directly demonstrates successful dynamic failover?","options":[{"id":"85-0","text":"Trip the duty pump under an approved controlled load and record flow, temperature, pressure and transfer timing.","feedback":"A controlled failure test measures whether the complete transport/control path maintains operating limits."},{"id":"85-1","text":"Inspect the spare pump's nameplate and declare the transfer successful.","feedback":"Installed capacity is not evidence of transfer performance."},{"id":"85-2","text":"Verify that the spare motor can run with the loop isolated.","feedback":"An isolated motor run does not prove loaded system continuity."},{"id":"85-3","text":"Count two pumps and infer any required availability rating.","feedback":"Availability includes common failures and dynamic behavior, not just unit count."}],"correct":"85-0","hint":"Test the intended failure scenario at the system boundary.","explanation":"A controlled failure test measures whether the complete transport/control path maintains operating limits.","trap":"Availability is a measured dynamic behavior, not just a count of installed pumps.","kind":"reasoning","domain":"thermal-fluid"},{"id":86,"prompt":"A saturated LOX tank at controlled pressure receives an extra 20 kW. Use hfg = 213 kJ/kg and assume latent-only vapor generation. Approximately what extra vapor rate follows?","options":[{"id":"86-0","text":"0.0939 kg/s; not a complete relief sizing result.","feedback":"20/213 = 0.0939 kg/s; final protection sizing needs additional state, flow and scenario information."},{"id":"86-1","text":"0.939 kg/s; therefore a certified relief capacity.","feedback":"The number is ten times too large, and an energy estimate is not certification."},{"id":"86-2","text":"0.00939 kg/s; independent of relieving pressure.","feedback":"The estimate is ten times too small; actual properties depend on state."},{"id":"86-3","text":"213 kg/s; because latent heat equals vapor mass rate.","feedback":"Specific energy and mass flow have different units."}],"correct":"86-0","hint":"Divide heat rate by the supplied specific phase-change energy.","explanation":"20/213 = 0.0939 kg/s; final protection sizing needs additional state, flow and scenario information.","trap":"A boil-off energy estimate does not certify pressure-relief capacity.","kind":"calculation","domain":"thermal-fluid"},{"id":87,"prompt":"A larger pipe costs $25,000 extra and saves 8 kW for 8000 h/year at $0.12/kWh. Ignoring all other differences, approximately what is simple payback?","options":[{"id":"87-0","text":"3.26 years","feedback":"Annual saving = 8×8000×0.12 = $7680; payback = 25,000/7680 = 3.26 years."},{"id":"87-1","text":"0.326 years","feedback":"This is ten times too short."},{"id":"87-2","text":"26.0 years","feedback":"This does not divide the added capital by the stated annual saving."},{"id":"87-3","text":"$7680 total upfront cost.","feedback":"$7680 is annual energy-cost saving, not the upfront premium."}],"correct":"87-0","hint":"Annualize the energy saving before dividing the capital premium.","explanation":"Annual saving = 8×8000×0.12 = $7680; payback = 25,000/7680 = 3.26 years.","trap":"State the assumed operating hours and energy boundary before reporting savings.","kind":"calculation","domain":"thermal-fluid"},{"id":88,"prompt":"An ideal gas parcel is reversibly compressed adiabatically from 1 to 20 bar absolute at initial 300 K, with γ = 1.4. T2 ≈ 706 K. What does this establish for an oxygen component?","options":[{"id":"88-0","text":"It illustrates compression heating, but does not predict a component-specific ignition outcome.","feedback":"A simplified gas-state estimate highlights a mechanism without modeling the full component transient or ignition."},{"id":"88-1","text":"It proves every oxygen valve ignites at a 20:1 ratio.","feedback":"No specific material, geometry or ignition criterion was supplied."},{"id":"88-2","text":"It proves actual fast filling is a reversible parcel compression.","feedback":"Actual filling is an open, irreversible and spatially varying event."},{"id":"88-3","text":"It eliminates the need to assess contaminants and materials.","feedback":"Those factors remain essential in an oxygen compatibility assessment."}],"correct":"88-0","hint":"Distinguish an illustrative mechanism from a qualified hazard prediction.","explanation":"A simplified gas-state estimate highlights a mechanism without modeling the full component transient or ignition.","trap":"A useful first-principles hazard illustration is not an ignition prediction.","kind":"reasoning","domain":"cycle"},{"id":89,"prompt":"A 120 kW rack uses water entering at 30°C. Bulk outlet limit is 40°C; cp = 4.18 kJ/(kg·K). Supplier minimum component flow is 4 kg/s. Which flow constraint governs?","options":[{"id":"89-0","text":"The supplier's 4 kg/s minimum; bulk outlet is about 37.2°C.","feedback":"The bulk minimum is 2.87 kg/s, below the component minimum; at 4 kg/s ΔT≈7.18 K."},{"id":"89-1","text":"The 2.87 kg/s bulk balance always overrides component limits.","feedback":"A local cold-plate limit can govern even when the bulk energy balance passes."},{"id":"89-2","text":"A 1 kg/s flow because the coolant remains liquid.","feedback":"Liquid state alone does not establish local heat-transfer adequacy."},{"id":"89-3","text":"Exactly 12 kg/s because load is 120 kW.","feedback":"This ignores the stated cp and temperature rise."}],"correct":"89-0","hint":"Compare all minimum-flow requirements and use the governing one.","explanation":"The bulk minimum is 2.87 kg/s, below the component minimum; at 4 kg/s ΔT≈7.18 K.","trap":"Bulk energy balance is necessary but may not set the minimum component flow.","kind":"calculation","domain":"thermal-fluid"},{"id":90,"prompt":"A 2 m simply supported beam carries 4 kN at 0.5 m from A. What are reactions A/B and maximum moment?","options":[{"id":"90-0","text":"3/1 kN; 1.5 kN·m.","feedback":"RB=4×0.5/2=1 kN; RA=3 kN; Mmax=3×0.5=1.5 kN·m."},{"id":"90-1","text":"2/2 kN; 2.0 kN·m.","feedback":"This is the symmetric midspan-load case, not the supplied location."},{"id":"90-2","text":"1/3 kN; 1.5 kN·m.","feedback":"This reverses the support reactions."},{"id":"90-3","text":"3/1 kN; 3.0 kN·m.","feedback":"Reactions are right but moment must use the 0.5 m lever arm to the load."}],"correct":"90-0","hint":"Use the actual load position, then the zero-crossing change in shear.","explanation":"RB=4×0.5/2=1 kN; RA=3 kN; Mmax=3×0.5=1.5 kN·m.","trap":"Use equilibrium and the load location rather than dividing the load equally by default.","kind":"calculation","graph":{"type":"beam","support":"simple","uniform":false,"length":2,"at":0.25,"label":"Downward load"},"domain":"structure"},{"id":91,"prompt":"Four identical parallel branches each carry 5 L/s at controlled header ΔP = 100 kPa. One branch closes. Ignore common-header losses and hold the same header ΔP. What is the new total flow?","options":[{"id":"91-0","text":"15 L/s; each open branch remains at 5 L/s.","feedback":"At unchanged branch resistance and pressure difference, open-branch flows stay unchanged."},{"id":"91-1","text":"20 L/s; each open branch rises to 6.67 L/s.","feedback":"This would require fixed-total-flow control and higher header differential."},{"id":"91-2","text":"10 L/s; every open branch must slow equally.","feedback":"The stated boundary holds differential pressure, not total flow."},{"id":"91-3","text":"25 L/s; the blocked branch increases source pressure automatically.","feedback":"The specified controller holds the same differential pressure."}],"correct":"91-0","hint":"Identify what the controller actually holds constant.","explanation":"At unchanged branch resistance and pressure difference, open-branch flows stay unchanged.","trap":"State what the controller actually holds constant before predicting the response.","kind":"reasoning","domain":"thermal-fluid"},{"id":92,"prompt":"A tank must contain 1000 tonnes of liquid methane at 420 kg/m³. Maximum liquid fraction is 90% of geometric volume; ignore heel. Approximately what geometric volume is needed?","options":[{"id":"92-0","text":"2646 m³","feedback":"Liquid volume is 1,000,000/420 = 2381 m³; divide by 0.90."},{"id":"92-1","text":"2381 m³","feedback":"2381 m³ is liquid volume before allowing the ullage fraction."},{"id":"92-2","text":"2143 m³","feedback":"Multiplying liquid volume by 0.90 makes a smaller tank that cannot hold the inventory."},{"id":"92-3","text":"26,460 m³","feedback":"This is a factor-of-ten mass or volume conversion error."}],"correct":"92-0","hint":"The liquid may occupy only 90% of the final tank volume.","explanation":"Liquid volume is 1,000,000/420 = 2381 m³; divide by 0.90.","trap":"Differentiate liquid volume, vessel geometric volume and deliverable inventory.","kind":"calculation","domain":"thermal-fluid"},{"id":93,"prompt":"A 1 kW chip has junction-to-local-coolant resistance 0.040 K/W and an 80°C junction limit. What maximum local coolant temperature is permitted in this lumped model?","options":[{"id":"93-0","text":"40°C","feedback":"The 40 K component rise leaves coolant at most 80−40 = 40°C."},{"id":"93-1","text":"80°C","feedback":"The component sits above coolant by QR, so coolant cannot equal the junction limit."},{"id":"93-2","text":"120°C","feedback":"This adds the thermal rise rather than subtracting it from the maximum junction temperature."},{"id":"93-3","text":"4°C","feedback":"QR is 40 K, not 4 K."}],"correct":"93-0","hint":"Work backward from the junction limit through the thermal resistance.","explanation":"The 40 K component rise leaves coolant at most 80−40 = 40°C.","trap":"Adequate total water flow does not guarantee every chip has adequate temperature margin.","kind":"calculation","domain":"thermal-fluid"},{"id":94,"prompt":"A 1 m steel tie rod has area 100 mm², load 10 kN and E = 200 GPa. What elastic elongation follows?","options":[{"id":"94-0","text":"0.50 mm","feedback":"δ=FL/(AE)=10,000×1/(0.0001×200×10⁹)=0.0005 m."},{"id":"94-1","text":"5.0 mm","feedback":"This is ten times the elastic displacement."},{"id":"94-2","text":"0.050 mm","feedback":"This is ten times too small."},{"id":"94-3","text":"50 mm","feedback":"This would imply a 5% strain rather than the supplied elastic response."}],"correct":"94-0","hint":"Use area in m² and modulus in Pa.","explanation":"δ=FL/(AE)=10,000×1/(0.0001×200×10⁹)=0.0005 m.","trap":"Stress, strain and displacement have different dimensions and geometry dependence.","kind":"calculation","domain":"structure"},{"id":95,"prompt":"An exchanger must transfer 500 kW with U = 1000 W/(m²·K), LMTD = 10 K and supplied configuration factor F = 0.90. Approximately what area is needed?","options":[{"id":"95-0","text":"55.6 m²","feedback":"A = 500,000/(1000×10×0.90) = 55.6 m²."},{"id":"95-1","text":"50.0 m²","feedback":"50 m² omits the correction factor."},{"id":"95-2","text":"45.0 m²","feedback":"Multiplying by F instead of dividing understates required area."},{"id":"95-3","text":"0.0556 m²","feedback":"This mixes a kW duty directly with a W-based U."}],"correct":"95-0","hint":"Write duty in watts and retain the supplied configuration factor.","explanation":"A = 500,000/(1000×10×0.90) = 55.6 m².","trap":"Track powers of 1000 explicitly when mixing kW duties and W-based coefficients.","kind":"calculation","domain":"thermal-fluid"},{"id":96,"prompt":"A liquefaction cold box loses capacity while feed-side ΔP rises after feed composition changes. Which hypothesis deserves early checking?","options":[{"id":"96-0","text":"Pretreatment breakthrough or deposition, alongside refrigeration and instrument checks.","feedback":"Changed feed and rising resistance can be consistent with deposition; measurements must distinguish it from other causes."},{"id":"96-1","text":"Water/CO₂ can be ignored because pipeline-quality gas can never freeze.","feedback":"Pipeline requirements need not meet deep-cryogenic cold-box requirements."},{"id":"96-2","text":"The change proves an undersized electrical supply is the only cause.","feedback":"The symptoms do not identify a unique cause."},{"id":"96-3","text":"Bypassing pretreatment is the most reliable first corrective action.","feedback":"Bypassing cleanup can worsen the very mechanism under investigation."}],"correct":"96-0","hint":"Link the changed composition and pressure-drop trend to testable mechanisms.","explanation":"Changed feed and rising resistance can be consistent with deposition; measurements must distinguish it from other causes.","trap":"Gas acceptable for pipeline transport can still be unsuitable for deep cryogenic processing.","kind":"reasoning","domain":"thermal-fluid"},{"id":97,"prompt":"100 US gpm of water removes 100 kW. Use 1 US gal = 3.785 L, ρ = 1000 kg/m³ and cp = 4.18 kJ/(kg·K). Approximately what temperature rise follows?","options":[{"id":"97-0","text":"3.79 K","feedback":"100 gpm = 6.308 L/s ≈6.308 kg/s; ΔT=100/(6.308×4.18)=3.79 K."},{"id":"97-1","text":"0.239 K","feedback":"This fails the required minutes-to-seconds flow conversion."},{"id":"97-2","text":"37.9 K","feedback":"This is ten times too large."},{"id":"97-3","text":"6.31 K","feedback":"6.31 is approximately the flow in L/s, not the temperature rise."}],"correct":"97-0","hint":"Convert gallons per minute all the way to kg per second.","explanation":"100 gpm = 6.308 L/s ≈6.308 kg/s; ΔT=100/(6.308×4.18)=3.79 K.","trap":"Most fast unit mistakes are avoidable if you say the physical quantity aloud.","kind":"calculation","domain":"thermal-fluid"},{"id":98,"prompt":"A standard cooling unit meets today's load and arrives soon; a custom unit is more efficient but delivery is uncertain. Which decision approach is most defensible?","options":[{"id":"98-0","text":"Compare dated load needs, mandatory constraints, delivery scenarios and complete lifecycle consequences.","feedback":"A feasible choice must meet the service date and operating requirements as well as cost and efficiency."},{"id":"98-1","text":"Choose the most efficient option regardless of when capacity is needed.","feedback":"A late efficient unit can still fail the operational requirement."},{"id":"98-2","text":"Choose the cheapest quotation without checking actual operating conditions.","feedback":"Initial price alone does not establish a feasible installed service."},{"id":"98-3","text":"Assume a custom unit's nameplate guarantees commissioned site performance.","feedback":"Acceptance depends on actual site conditions, integration and verification."}],"correct":"98-0","hint":"Start with the nonnegotiable service requirement and schedule.","explanation":"A feasible choice must meet the service date and operating requirements as well as cost and efficiency.","trap":"Do not invent a procurement success story to make a hypothetical decision sound stronger.","kind":"reasoning","domain":"thermal-fluid"},{"id":99,"prompt":"A fully filled closed 2 MW water loop permits a 10 K rise. At the resulting flow, pipe/fittings lose 23.2 kPa, exchanger 60, cold plates 50 and control valves 30 kPa. What circulating pump differential is required?","options":[{"id":"99-0","text":"163.2 kPa, before any new design allowance.","feedback":"Add losses at the same operating flow: 23.2+60+50+30=163.2 kPa."},{"id":"99-1","text":"140 kPa because pipe losses are already implicit.","feedback":"The problem lists pipe/fittings as a separate loss that must be included."},{"id":"99-2","text":"23.2 kPa because closed loops cancel all component loss.","feedback":"A closed path cancels net elevation, not dissipative losses."},{"id":"99-3","text":"163.2 kPa plus 30 m head solely because the building is tall.","feedback":"A filled return loop does not require adding the full building elevation as net static head."}],"correct":"99-0","hint":"Sum consistent design-flow losses around the complete closed circuit.","explanation":"Add losses at the same operating flow: 23.2+60+50+30=163.2 kPa.","trap":"Do not add building elevation as net static head around the stated filled closed loop.","kind":"reasoning","domain":"thermal-fluid"},{"id":100,"prompt":"A hypothetical liquefier has net cold duty 3 MW at COP 0.25. A compute chiller removes 10 MW at COP 5. Under these defined cycle boundaries, what combined compressor input and ambient heat rejection follow?","options":[{"id":"100-0","text":"14 MW input; 27 MW rejection.","feedback":"Input=3/0.25+10/5=14 MW; rejection=(3+12)+(10+2)=27 MW."},{"id":"100-1","text":"13 MW input; 14 MW rejection.","feedback":"The two powers must be calculated from their own supplied COPs."},{"id":"100-2","text":"3 MW input; 16 MW rejection.","feedback":"This understates the liquefier work required at COP 0.25."},{"id":"100-3","text":"14 MW input; 13 MW rejection.","feedback":"13 MW is total cold duty; ambient rejection also includes the 14 MW work input."}],"correct":"100-0","hint":"Close each refrigeration-cycle energy balance before combining them.","explanation":"Input=3/0.25+10/5=14 MW; rejection=(3+12)+(10+2)=27 MW.","trap":"A compute cooling loop and a cryogenic liquefier operate at very different temperature levels.","kind":"calculation","domain":"cycle"},{"id":101,"prompt":"The pump runs at fixed speed. The system's quadratic resistance increases while static head is unchanged. Which shift of operating point follows?","options":[{"id":"101-0","text":"Lower flow and higher pump head.","feedback":"The steeper system curve intersects the descending pump curve farther left and higher."},{"id":"101-1","text":"Higher flow and higher pump head.","feedback":"Higher resistance does not move this stable intersection to higher flow."},{"id":"101-2","text":"Lower flow and lower pump head.","feedback":"On this descending curve, moving left increases head."},{"id":"101-3","text":"Exactly the same flow and head.","feedback":"The system curve and its intersection changed."}],"correct":"101-0","hint":"Trace the new intersection along the unchanged pump curve.","explanation":"The steeper system curve intersects the descending pump curve farther left and higher.","trap":"","kind":"reasoning","graph":{"type":"plot","xLabel":"Flow (m³/h)","yLabel":"Head (m)","xMax":55,"yMax":65,"series":[{"label":"Pump","kind":"poly","coeff":[60,0,-0.02],"color":"blue","dash":false},{"label":"Original system","kind":"poly","coeff":[10,0,0.02],"color":"orange","dash":false},{"label":"More resistance","kind":"poly","coeff":[10,0,0.045],"color":"orange","dash":true}]},"domain":"thermal-fluid"},{"id":102,"prompt":"In this fixed-speed system, static head decreases while friction coefficient is constant. What happens to the stable operating point?","options":[{"id":"102-0","text":"Flow increases and pump head decreases.","feedback":"Lowering the system curve moves the intersection right and down on the unchanged pump curve."},{"id":"102-1","text":"Flow decreases and pump head increases.","feedback":"That is the opposite direction for the displayed change."},{"id":"102-2","text":"Flow increases and pump head increases.","feedback":"This pump curve descends, so higher flow has lower head."},{"id":"102-3","text":"The pump curve shifts upward without a speed change.","feedback":"Changing the system boundary does not shift the pump characteristic."}],"correct":"102-0","hint":"Separate a system-curve shift from a pump-curve shift.","explanation":"Lowering the system curve moves the intersection right and down on the unchanged pump curve.","trap":"","kind":"reasoning","graph":{"type":"plot","xLabel":"Flow (m³/h)","yLabel":"Head (m)","xMax":55,"yMax":65,"series":[{"label":"Pump","kind":"poly","coeff":[60,0,-0.02],"color":"blue","dash":false},{"label":"Original system","kind":"poly","coeff":[25,0,0.02],"color":"orange","dash":false},{"label":"Lower static head","kind":"poly","coeff":[5,0,0.02],"color":"orange","dash":true}]},"domain":"thermal-fluid"},{"id":103,"prompt":"The system has zero static head and loss exactly proportional to Q². A similar pump increases speed by 10% at constant efficiency. What are the flow and power ratios?","options":[{"id":"103-0","text":"Flow ×1.10; power ×1.331.","feedback":"For this quadratic system, Q∝N and P∝N³."},{"id":"103-1","text":"Flow ×1.10; power ×1.10.","feedback":"Power is cubic rather than linear in the supplied similarity model."},{"id":"103-2","text":"Flow ×1.21; power ×1.331.","feedback":"1.21 is the head ratio, not the flow ratio."},{"id":"103-3","text":"Flow ×1.00; power ×1.21.","feedback":"The intersection moves to a different flow."}],"correct":"103-0","hint":"Zero static head makes exact speed-flow scaling possible.","explanation":"For this quadratic system, Q∝N and P∝N³.","trap":"","kind":"calculation","graph":{"type":"plot","xLabel":"Flow (m³/h)","yLabel":"Head (m)","xMax":55,"yMax":65,"series":[{"label":"100% speed","kind":"poly","coeff":[45,0,-0.02],"color":"blue","dash":false},{"label":"110% speed","kind":"poly","coeff":[54.45,0,-0.02],"color":"blue","dash":true},{"label":"System","kind":"poly","coeff":[0,0,0.02],"color":"orange","dash":false}]},"domain":"thermal-fluid"},{"id":104,"prompt":"Two identical pumps are in series. At a specified common flow, how is their ideal combined curve constructed?","options":[{"id":"104-0","text":"Add the two heads at that flow.","feedback":"Series pumps carry common flow and ideally add head; the system still determines the intersection."},{"id":"104-1","text":"Add their flows at the same head.","feedback":"Adding flow at common head describes parallel pumps."},{"id":"104-2","text":"Keep single-pump head at every flow.","feedback":"Two series pumps can supply more head."},{"id":"104-3","text":"Double actual system flow for every system curve.","feedback":"System resistance prevents a universal doubling of operating flow."}],"correct":"104-0","hint":"Follow one stream through one pump and then the other.","explanation":"Series pumps carry common flow and ideally add head; the system still determines the intersection.","trap":"","kind":"reasoning","graph":{"type":"plot","xLabel":"Flow (m³/h)","yLabel":"Head (m)","xMax":60,"yMax":90,"series":[{"label":"One pump","kind":"poly","coeff":[40,0,-0.01],"color":"blue","dash":false},{"label":"Two in series","kind":"poly","coeff":[80,0,-0.02],"color":"blue","dash":true},{"label":"System","kind":"poly","coeff":[0,0,0.02],"color":"orange","dash":false}]},"domain":"thermal-fluid"},{"id":105,"prompt":"The dashed curve represents two pumps in parallel. How is it constructed from two identical single-pump curves?","options":[{"id":"105-0","text":"At each common head, add the flows.","feedback":"Parallel pumps feed a common head, and their contributions to flow add."},{"id":"105-1","text":"At each common flow, add the heads.","feedback":"That is series construction."},{"id":"105-2","text":"At each flow, multiply head by four.","feedback":"Parallel connection has no universal fourfold-head relation."},{"id":"105-3","text":"Subtract one pump head from the system curve.","feedback":"The external system curve has not changed."}],"correct":"105-0","hint":"Both parallel outlets feed the same header pressure.","explanation":"Parallel pumps feed a common head, and their contributions to flow add.","trap":"","kind":"reasoning","graph":{"type":"plot","xLabel":"Flow (m³/h)","yLabel":"Head (m)","xMax":65,"yMax":48,"series":[{"label":"One pump","kind":"poly","coeff":[40,0,-0.01],"color":"blue","dash":false},{"label":"Parallel pair","kind":"poly","coeff":[40,0,-0.0025],"color":"blue","dash":true},{"label":"System","kind":"poly","coeff":[0,0,0.02],"color":"orange","dash":false}]},"domain":"thermal-fluid"},{"id":106,"prompt":"What happens as flow rises toward the crossing of these illustrative NPSH curves?","options":[{"id":"106-0","text":"Available-minus-required NPSH shrinks toward zero.","feedback":"The available curve decreases while the required curve increases."},{"id":"106-1","text":"The NPSH margin must grow because flow increases.","feedback":"The plotted suction-loss effect reduces available NPSH."},{"id":"106-2","text":"Discharge head guarantees no suction cavitation.","feedback":"Suction state and pump requirements govern this comparison."},{"id":"106-3","text":"Equality proves a universally sufficient design margin.","feedback":"Application-specific margin requirements can be stricter than equality."}],"correct":"106-0","hint":"Compare the vertical separation between the curves.","explanation":"The available curve decreases while the required curve increases.","trap":"","kind":"reasoning","graph":{"type":"plot","xLabel":"Flow (m³/h)","yLabel":"NPSH (m)","xMax":40,"yMax":16,"series":[{"label":"Available","kind":"poly","coeff":[14,0,-0.008],"color":"blue","dash":false},{"label":"Required","kind":"poly","coeff":[2,0,0.002],"color":"orange","dash":false}]},"domain":"thermal-fluid"},{"id":107,"prompt":"Two parallel branches see 120 kPa differential. ΔP=3QA² and ΔP=12QB², in kPa and L/s. Approximately what is the split?","options":[{"id":"107-0","text":"QA=6.32 L/s; QB=3.16 L/s.","feedback":"Solve each curve at common pressure: √(120/3) and √(120/12)."},{"id":"107-1","text":"QA=3.16 L/s; QB=6.32 L/s.","feedback":"The high-resistance branch carries less flow."},{"id":"107-2","text":"QA=QB=5.00 L/s.","feedback":"Equal pressure does not require equal flow with unequal resistances."},{"id":"107-3","text":"QA=40 L/s; QB=10 L/s.","feedback":"40 and 10 are squared flows, not flows."}],"correct":"107-0","hint":"Read the two flows at the same horizontal pressure level.","explanation":"Solve each curve at common pressure: √(120/3) and √(120/12).","trap":"","kind":"calculation","graph":{"type":"plot","xLabel":"Branch flow (L/s)","yLabel":"Loss (kPa)","xMax":8,"yMax":160,"series":[{"label":"Branch A","kind":"poly","coeff":[0,0,3],"color":"blue","dash":false},{"label":"Branch B","kind":"poly","coeff":[0,0,12],"color":"orange","dash":false},{"label":"Header differential","kind":"poly","coeff":[120,0,0],"color":"grey","dash":true}]},"domain":"thermal-fluid"},{"id":108,"prompt":"The graph shows bulk water rise at fixed 418 kW and cp=4.18 kJ/(kg·K). Doubling flow from 10 to 20 kg/s does what?","options":[{"id":"108-0","text":"Reduces rise from 10 K to 5 K.","feedback":"ΔT=Q/(ṁcp), so doubling flow halves the bulk rise."},{"id":"108-1","text":"Increases rise from 10 K to 20 K.","feedback":"This reverses the energy-balance dependence."},{"id":"108-2","text":"Keeps rise at 10 K.","feedback":"Fixed duty requires a changed rise when flow changes."},{"id":"108-3","text":"Reduces rise to zero.","feedback":"Finite flow needs finite temperature change to carry nonzero heat."}],"correct":"108-0","hint":"Use the whole-stream energy balance.","explanation":"ΔT=Q/(ṁcp), so doubling flow halves the bulk rise.","trap":"","kind":"calculation","graph":{"type":"plot","xLabel":"Water flow (kg/s)","yLabel":"Bulk rise (K)","xMax":40,"yMax":22,"series":[{"label":"Fixed 418 kW","kind":"power","a":100,"p":-1,"color":"blue"}],"xMin":5},"domain":"thermal-fluid"},{"id":109,"prompt":"At the same steady series heat rate, node temperatures are junction 80°C, case 75°C, base 65°C and coolant 35°C. Which segment has greatest thermal resistance?","options":[{"id":"109-0","text":"Base-to-coolant.","feedback":"R=ΔT/Q at a common heat rate; the 30 K final drop is largest."},{"id":"109-1","text":"Junction-to-case.","feedback":"Its temperature drop is only 5 K."},{"id":"109-2","text":"Case-to-base.","feedback":"Its temperature drop is 10 K, below 30 K."},{"id":"109-3","text":"All three are equal.","feedback":"Equal heat rate does not imply equal series resistance."}],"correct":"109-0","hint":"Compare temperature drops, not drawn segment lengths.","explanation":"R=ΔT/Q at a common heat rate; the 30 K final drop is largest.","trap":"","kind":"reasoning","graph":{"type":"plot","xLabel":"Node along heat path","yLabel":"Temperature (°C)","xMax":3,"yMax":90,"series":[{"label":"Temperature","kind":"points","points":[[0,80],[1,75],[2,65],[3,35]],"color":"blue"}],"xTicks":[[0,"J"],[1,"Case"],[2,"Base"],[3,"Coolant"]]},"domain":"thermal-fluid"},{"id":110,"prompt":"A lumped body cools from 80°C toward 20°C with τ=60 s. After one time constant, approximately what fraction of its INITIAL EXCESS above ambient remains?","options":[{"id":"110-0","text":"36.8%","feedback":"Excess temperature follows exp(−t/τ), giving e⁻¹=0.368 at t=τ."},{"id":"110-1","text":"63.2%","feedback":"63.2% is the excess removed, not remaining."},{"id":"110-2","text":"50.0%","feedback":"The half-life is τ ln 2, not τ."},{"id":"110-3","text":"0%","feedback":"The simple exponential reaches ambient only asymptotically."}],"correct":"110-0","hint":"Apply the exponential to temperature above ambient.","explanation":"Excess temperature follows exp(−t/τ), giving e⁻¹=0.368 at t=τ.","trap":"","kind":"calculation","graph":{"type":"plot","xLabel":"Time (s)","yLabel":"Temperature (°C)","xMax":180,"yMax":90,"series":[{"label":"Cooling body","kind":"exp","base":20,"amp":60,"tau":60,"color":"blue"},{"label":"Ambient","kind":"poly","coeff":[20,0,0],"color":"grey","dash":true}]},"domain":"thermal-fluid"},{"id":111,"prompt":"This shear diagram is for a simply supported 6 m beam under uniform downward load. Where is the largest positive bending moment?","options":[{"id":"111-0","text":"At x=3 m, where shear crosses zero.","feedback":"dM/dx=V, so the moment peaks where shear changes from positive to negative."},{"id":"111-1","text":"At x=0, where shear is largest positive.","feedback":"Shear is moment slope, not moment magnitude."},{"id":"111-2","text":"At x=6 m, where shear is most negative.","feedback":"The ideal simple support carries no end moment in this case."},{"id":"111-3","text":"Everywhere, because distributed load is constant.","feedback":"Constant uniform load produces linear shear and parabolic moment."}],"correct":"111-0","hint":"Moment accumulates as area under the shear diagram.","explanation":"dM/dx=V, so the moment peaks where shear changes from positive to negative.","trap":"","kind":"reasoning","graph":{"type":"plot","xLabel":"Position x (m)","yLabel":"Shear (kN)","xMax":6,"yMax":7,"series":[{"label":"Shear","kind":"poly","coeff":[6,-2,0],"color":"blue","dash":false}],"yMin":-7},"domain":"structure"},{"id":112,"prompt":"The plot shows bending moment MAGNITUDE in a uniform cantilever with downward tip load. Where is nominal bending stress greatest?","options":[{"id":"112-0","text":"At the fixed wall, x=0.","feedback":"With constant section modulus, maximum |M| gives maximum |σ|, at the wall."},{"id":"112-1","text":"At the free tip, x=3 m.","feedback":"The moment magnitude approaches zero at the free end."},{"id":"112-2","text":"At midspan, x=1.5 m.","feedback":"The plotted maximum is at the wall."},{"id":"112-3","text":"Uniform along the span.","feedback":"Constant shear makes moment linear, not constant."}],"correct":"112-0","hint":"Compare the plotted moment magnitudes.","explanation":"With constant section modulus, maximum |M| gives maximum |σ|, at the wall.","trap":"","kind":"reasoning","graph":{"type":"plot","xLabel":"Distance from wall (m)","yLabel":"Moment magnitude (kN·m)","xMax":3,"yMax":7,"series":[{"label":"Moment magnitude","kind":"poly","coeff":[6,-2,0],"color":"blue","dash":false}]},"domain":"structure"},{"id":113,"prompt":"For fixed E, I and end condition, this ideal Euler curve has Pcr∝1/L². Doubling unsupported length from 1 to 2 m does what?","options":[{"id":"113-0","text":"Reduces critical load to one quarter.","feedback":"The denominator grows by 2², giving a load fraction of 1/4."},{"id":"113-1","text":"Reduces critical load to one half.","feedback":"That would require inverse-linear length dependence."},{"id":"113-2","text":"Doubles critical load.","feedback":"A longer slender column has lower critical load."},{"id":"113-3","text":"Leaves critical load unchanged.","feedback":"Buckling is sensitive to unsupported length."}],"correct":"113-0","hint":"Square the length ratio in the denominator.","explanation":"The denominator grows by 2², giving a load fraction of 1/4.","trap":"","kind":"calculation","graph":{"type":"plot","xLabel":"Unsupported length (m)","yLabel":"Euler load (kN)","xMax":3,"yMax":70,"series":[{"label":"Fixed section and ends","kind":"power","a":16,"p":-2,"color":"blue"}],"xMin":0.5},"domain":"structure"},{"id":114,"prompt":"These are schematic counterflow endpoint profiles: hot 50→39.5°C and cold 20→41°C flowing oppositely. What is the correct reading?","options":[{"id":"114-0","text":"The outlet crossover need not mean local heat-flow reversal.","feedback":"The two outlets occupy opposite ends; local end differences are positive 9 K and 19.5 K."},{"id":"114-1","text":"Any outlet crossover violates the second law.","feedback":"Compare temperatures at the same position, not outlets at opposite ends."},{"id":"114-2","text":"Both local terminal differences are negative.","feedback":"Hot fluid is above cold at both displayed ends."},{"id":"114-3","text":"The right-hand cold value is the cold outlet despite the stated direction.","feedback":"Cold flow direction is opposite the hot flow here."}],"correct":"114-0","hint":"Pair hot and cold temperatures at each physical end.","explanation":"The two outlets occupy opposite ends; local end differences are positive 9 K and 19.5 K.","trap":"","kind":"reasoning","graph":{"type":"plot","xLabel":"Physical position","yLabel":"Temperature (°C)","xMax":1,"yMax":60,"series":[{"label":"Hot: left to right","kind":"points","points":[[0,50],[1,39.5]],"color":"orange"},{"label":"Cold: right to left","kind":"points","points":[[0,41],[1,20]],"color":"blue"}],"xTicks":[[0,"End 1"],[1,"End 2"]],"caption":"Endpoint schematic. The connecting lines do not represent a resolved local heat-transfer solution."},"domain":"thermal-fluid"},{"id":115,"prompt":"For this counterflow exchanger, terminal differences are 10 K and 5 K. Approximately what is LMTD?","options":[{"id":"115-0","text":"7.21 K","feedback":"(10−5)/ln(10/5)=7.21 K."},{"id":"115-1","text":"7.50 K","feedback":"7.50 K is the arithmetic mean."},{"id":"115-2","text":"5.00 K","feedback":"5 K is only the smaller terminal approach."},{"id":"115-3","text":"15.0 K","feedback":"Terminal differences are not added to form LMTD."}],"correct":"115-0","hint":"Use the logarithmic rather than arithmetic mean.","explanation":"(10−5)/ln(10/5)=7.21 K.","trap":"","kind":"calculation","graph":{"type":"plot","xLabel":"Physical position","yLabel":"Temperature (°C)","xMax":1,"yMax":70,"series":[{"label":"Hot","kind":"points","points":[[0,60],[1,30]],"color":"orange"},{"label":"Cold","kind":"points","points":[[0,50],[1,25]],"color":"blue"}],"xTicks":[[0,"End 1"],[1,"End 2"]],"caption":"Endpoint schematic. The connecting lines do not represent a resolved local heat-transfer solution."},"domain":"thermal-fluid"},{"id":116,"prompt":"The curve is reversible refrigerator COP=Tc/(300−Tc). For the SAME cold duty, how does minimum required work change as Tc decreases?","options":[{"id":"116-0","text":"It increases because COP decreases.","feedback":"Minimum work is Qcold/COP; lower Tc at fixed hot sink means lower COP."},{"id":"116-1","text":"It decreases because cold fluid stores less energy.","feedback":"Stored energy alone does not determine temperature-lift work."},{"id":"116-2","text":"It stays constant because duty is fixed.","feedback":"Changing COP changes required work even at fixed duty."},{"id":"116-3","text":"It tends to zero as Tc tends to absolute zero.","feedback":"The stated reversible relation does not make the work vanish."}],"correct":"116-0","hint":"Compare work per unit cooling as the temperature lift increases.","explanation":"Minimum work is Qcold/COP; lower Tc at fixed hot sink means lower COP.","trap":"","kind":"reasoning","graph":{"type":"plot","xLabel":"Cold reservoir Tc (K)","yLabel":"Carnot COP","xMax":280,"yMax":16,"series":[{"label":"Hot reservoir 300 K","kind":"ratio","hot":300,"color":"blue"}],"xMin":80},"domain":"cycle"},{"id":117,"prompt":"A sealed rigid ideal-gas vessel is at 6 bar absolute, or 5 bar gauge, at 300 K. It warms to 330 K; atmosphere stays 1 bar. What is final gauge pressure?","options":[{"id":"117-0","text":"5.6 bar gauge.","feedback":"Absolute pressure becomes 6×330/300=6.6 bar; subtract atmosphere."},{"id":"117-1","text":"5.5 bar gauge.","feedback":"This scales gauge pressure directly instead of absolute pressure."},{"id":"117-2","text":"6.6 bar gauge.","feedback":"6.6 bar is the final absolute pressure."},{"id":"117-3","text":"6.0 bar gauge.","feedback":"This is not the temperature-scaled gas-law result."}],"correct":"117-0","hint":"The origin relation uses absolute pressure and kelvin.","explanation":"Absolute pressure becomes 6×330/300=6.6 bar; subtract atmosphere.","trap":"","kind":"calculation","graph":{"type":"plot","xLabel":"Gas temperature (K)","yLabel":"Pressure (bar)","xMax":400,"yMax":9,"series":[{"label":"Absolute pressure","kind":"poly","coeff":[0,0.02,0],"color":"blue","dash":false},{"label":"Gauge pressure","kind":"poly","coeff":[-1,0.02,0],"color":"orange","dash":false}],"xMin":200},"domain":"thermal-fluid"},{"id":118,"prompt":"These curves compare losses at fixed flow, fixed Darcy f and unchanged fitting K. Doubling diameter changes the straight-pipe and fitting losses to what fractions?","options":[{"id":"118-0","text":"1/32 and 1/16.","feedback":"Straight-pipe loss∝D⁻⁵ and local loss∝D⁻⁴, giving 2⁻⁵ and 2⁻⁴."},{"id":"118-1","text":"1/16 and 1/32.","feedback":"The two exponents are reversed."},{"id":"118-2","text":"1/4 and 1/4.","feedback":"1/4 is the velocity fraction, not pressure-loss fraction."},{"id":"118-3","text":"1/2 and 1/2.","feedback":"Neither pressure-loss term is linear in diameter at fixed flow."}],"correct":"118-0","hint":"Track the extra 1/D multiplying the straight-pipe velocity-squared term.","explanation":"Straight-pipe loss∝D⁻⁵ and local loss∝D⁻⁴, giving 2⁻⁵ and 2⁻⁴.","trap":"","kind":"calculation","graph":{"type":"plot","xLabel":"Pipe ID (mm)","yLabel":"Relative loss scale","xMax":100,"yMax":350,"series":[{"label":"Straight pipe","kind":"power","a":31250000000,"p":-5,"color":"blue"},{"label":"Fittings","kind":"power","a":625000000,"p":-4,"color":"orange"}],"xMin":40},"domain":"thermal-fluid"},{"id":119,"prompt":"Water flow stays at 40 kg/s with cp=4.18 kJ/(kg·K). Heat input steps from 1 to 2 MW. At the NEW steady state, approximately how does bulk temperature rise change?","options":[{"id":"119-0","text":"From 5.98 K to 11.96 K.","feedback":"At fixed mass flow and cp, ΔT=Q/(ṁcp), so doubling duty doubles rise."},{"id":"119-1","text":"From 5.98 K to 2.99 K.","feedback":"That would follow from doubling flow at fixed duty."},{"id":"119-2","text":"It stays at 5.98 K.","feedback":"Unchanged pump operation does not fix coolant rise as load changes."},{"id":"119-3","text":"It becomes infinite.","feedback":"A finite duty and finite flow give a finite steady rise."}],"correct":"119-0","hint":"The question asks for the new steady state, not the instantaneous transient.","explanation":"At fixed mass flow and cp, ΔT=Q/(ṁcp), so doubling duty doubles rise.","trap":"","kind":"calculation","graph":{"type":"plot","xLabel":"Time (s)","yLabel":"Heat input (MW)","xMax":120,"yMax":2.5,"series":[{"label":"Load","kind":"points","points":[[0,1],[60,1],[60,2],[120,2]],"color":"orange"}]},"domain":"thermal-fluid"},{"id":120,"prompt":"Capacity falls linearly from 5 MW at 30°C ambient to 3.5 MW at 45°C. Duty is constant 4 MW. Under this rating model, what is the highest feasible ambient on capacity alone?","options":[{"id":"120-0","text":"40°C","feedback":"Capacity=8−0.1Tamb MW; equality with 4 MW occurs at 40°C."},{"id":"120-1","text":"35°C","feedback":"At 35°C there is still 4.5 MW capacity."},{"id":"120-2","text":"45°C","feedback":"At 45°C only 3.5 MW is available."},{"id":"120-3","text":"50°C","feedback":"At 50°C only 3 MW is available."}],"correct":"120-0","hint":"Find the intersection of declining available capacity and constant duty.","explanation":"Capacity=8−0.1Tamb MW; equality with 4 MW occurs at 40°C.","trap":"","kind":"calculation","graph":{"type":"plot","xLabel":"Ambient (°C)","yLabel":"Capacity / duty (MW)","xMax":50,"yMax":6,"series":[{"label":"Available","kind":"poly","coeff":[8,-0.1,0],"color":"blue","dash":false},{"label":"Duty","kind":"poly","coeff":[4,0,0],"color":"orange","dash":true}],"xMin":20,"revealPoints":[{"x":40,"y":4,"label":"Limit"}]},"domain":"thermal-fluid"},{"id":121,"prompt":"A power plant pumps liquid water, adds heat to vaporize it, expands steam through a turbine and condenses the exhaust. Which ideal cycle is the closest description?","options":[{"id":"121-0","text":"Rankine power cycle.","feedback":"The liquid pump, boiler, turbine and condenser are the defining simple Rankine components."},{"id":"121-1","text":"Reverse Brayton refrigeration cycle.","feedback":"Reverse Brayton uses a gas compression/expansion refrigeration loop with net work input."},{"id":"121-2","text":"Vapor-compression refrigeration cycle.","feedback":"A vapor-compression refrigerator uses a compressor and expansion device to provide cooling."},{"id":"121-3","text":"Simple Linde–Hampson liquefaction cycle.","feedback":"The simple Linde–Hampson process uses recuperation and JT expansion for liquefaction rather than a steam power loop."}],"correct":"121-0","hint":"Track the working-fluid phase at the compression device.","explanation":"The liquid pump, boiler, turbine and condenser are the defining simple Rankine components.","trap":"","kind":"reasoning","graph":{"type":"cycle","labels":["Liquid pump","Boiler","Steam turbine","Condenser"]},"domain":"cycle"},{"id":122,"prompt":"A gas-turbine generator compresses gas, adds heat, expands it to produce work and rejects heat. Which ideal power-cycle model is the usual starting point?","options":[{"id":"122-0","text":"Brayton power cycle.","feedback":"The ideal Brayton power cycle models gas compression, heat addition, expansion and heat rejection."},{"id":"122-1","text":"Rankine power cycle.","feedback":"Rankine normally compresses liquid and includes vaporization/condensation."},{"id":"122-2","text":"Absorption refrigeration cycle.","feedback":"Absorption is a heat-driven refrigeration system, not this gas-turbine power loop."},{"id":"122-3","text":"Linde–Hampson liquefaction cycle.","feedback":"A JT liquefaction loop is not the described work-producing gas-turbine cycle."}],"correct":"122-0","hint":"The compressor handles gas rather than a condensed liquid.","explanation":"This is an ideal Brayton power-cycle pattern: isentropic gas compression, constant-pressure heating, isentropic expansion and constant-pressure heat rejection.\n\nThe schematic uses T1=300 K, T2=600 K, T3=1200 K and T4=600 K. Net specific work is cp[(1200−600)−(600−300)]=300cp, positive in the power-cycle direction.","trap":"","kind":"reasoning","graph":{"type":"plot","xLabel":"Relative entropy s/cp","yLabel":"Temperature (K)","xMax":0.6931471805599453,"yMax":1300,"noData":true,"xTicks":[[0,"0"],[0.34657359027997264,"0.35"],[0.6931471805599453,"0.69"]],"series":[{"label":"Ideal compression","kind":"points","points":[[0,300],[0,600]],"color":"blue"},{"label":"High-pressure heating","kind":"exp","base":0,"amp":600,"tau":-1,"color":"orange"},{"label":"Ideal expansion","kind":"points","points":[[0.6931471805599453,1200],[0.6931471805599453,600]],"color":"blue","dash":true},{"label":"Low-pressure cooling","kind":"exp","base":0,"amp":300,"tau":-1,"color":"grey"}],"caption":"Ideal-gas T–s schematic with constant cp. The vertical branches are isentropic; the curved branches are constant-pressure heating and cooling."},"domain":"cycle"},{"id":123,"prompt":"In the conventional vapor-compression refrigeration loop shown, which component is modeled as approximately isenthalpic under steady adiabatic, no-work, negligible-KE/PE assumptions?","options":[{"id":"123-0","text":"The expansion valve.","feedback":"The valve has negligible heat and work transfer, so its flow enthalpy stays approximately constant."},{"id":"123-1","text":"The compressor.","feedback":"The compressor adds shaft work and normally raises enthalpy."},{"id":"123-2","text":"The condenser.","feedback":"The condenser rejects heat and reduces refrigerant enthalpy."},{"id":"123-3","text":"The evaporator.","feedback":"The evaporator absorbs heat and raises refrigerant enthalpy."}],"correct":"123-0","hint":"Use the steady-flow energy equation for each device.","explanation":"The valve has negligible heat and work transfer, so its flow enthalpy stays approximately constant.","trap":"","kind":"reasoning","graph":{"type":"plot","xLabel":"Specific enthalpy (kJ/kg)","yLabel":"Pressure (bar)","xMin":200,"xMax":480,"yMax":15,"noData":true,"series":[{"label":"1 → 2: compression","kind":"points","points":[[400,3],[440,12]],"color":"blue"},{"label":"2 → 3: heat rejection","kind":"points","points":[[440,12],[250,12]],"color":"orange"},{"label":"3 → 4: throttling","kind":"points","points":[[250,12],[250,3]],"color":"blue","dash":true},{"label":"4 → 1: evaporation","kind":"points","points":[[250,3],[400,3]],"color":"grey"}],"caption":"Schematic p–h state path on linear pressure axes; illustrative values are not refrigerant property data. The compressor path is drawn straight for clarity."},"domain":"cycle"},{"id":124,"prompt":"In an idealized vapor-compression cycle, condenser-liquid subcooling lowers h3 while compressor inlet/outlet enthalpies and mass flow stay fixed. The valve has h4=h3. What happens to evaporator duty?","options":[{"id":"124-0","text":"It increases because h1−h4 increases.","feedback":"Qevap=ṁ(h1−h4); lower h4 increases the refrigeration effect under the explicitly fixed other states."},{"id":"124-1","text":"It decreases because colder refrigerant cannot absorb heat.","feedback":"A lower inlet enthalpy can absorb more energy before reaching the same outlet state."},{"id":"124-2","text":"It stays fixed because compressor power is fixed.","feedback":"At fixed compressor work, an increased refrigeration effect changes duty and COP."},{"id":"124-3","text":"It becomes zero because the valve is isenthalpic.","feedback":"Isenthalpic throttling does not imply no subsequent heat absorption."}],"correct":"124-0","hint":"Compare the evaporator enthalpy difference before and after subcooling.","explanation":"Qevap=ṁ(h1−h4); lower h4 increases the refrigeration effect under the explicitly fixed other states.","trap":"","kind":"reasoning","domain":"cycle"},{"id":125,"prompt":"A site has steady waste steam at conditions a supplier confirms can drive an absorption chiller, year-round chilled-water demand, limited electrical capacity and adequate heat rejection. Which option most directly uses the available thermal resource?","options":[{"id":"125-0","text":"Evaluate a heat-driven absorption chiller.","feedback":"Absorption can use thermal input to drive cooling, but source conditions, capacity, heat rejection and economics still need verification."},{"id":"125-1","text":"Use a Rankine turbine alone as the chilled-water heat exchanger.","feedback":"A turbine alone does not provide the complete chilled-water refrigeration service."},{"id":"125-2","text":"Assume a dry cooler can always produce 7°C water in 35°C air.","feedback":"Passive dry cooling cannot deliver that sub-ambient temperature under those conditions."},{"id":"125-3","text":"Remove all heat rejection because the driving heat is waste heat.","feedback":"The driving heat still enters the overall heat balance and must ultimately be rejected."}],"correct":"125-0","hint":"Distinguish the driving energy source from the cold duty.","explanation":"Absorption can use thermal input to drive cooling, but source conditions, capacity, heat rejection and economics still need verification.","trap":"","kind":"reasoning","domain":"cycle"},{"id":126,"prompt":"A compute loop needs 30°C supply. Outdoor dry-bulb is 15°C and a suitably rated dry cooler plus exchanger needs a total 8 K approach. Which option should be investigated first for this condition?","options":[{"id":"126-0","text":"Water-side economizer/free cooling, with pumping and fan power.","feedback":"The stated passive leaving-temperature limit is 15+8=23°C, below the required supply, so economizer operation is temperature-feasible subject to capacity."},{"id":"126-1","text":"Deep cryogenic refrigeration solely because compute is high performance.","feedback":"The required temperature does not call for a cryogenic cycle."},{"id":"126-2","text":"A heat engine delivering 30°C cooling with no heat sink.","feedback":"Cooling needs a heat-transfer/refrigeration path, not a heat-engine label alone."},{"id":"126-3","text":"A heater to raise the heat-rejection sink above 30°C.","feedback":"Raising sink temperature reduces the available passive driving difference."}],"correct":"126-0","hint":"Check the temperature feasibility before choosing an active refrigeration cycle.","explanation":"The stated passive leaving-temperature limit is 15+8=23°C, below the required supply, so economizer operation is temperature-feasible subject to capacity.","trap":"","kind":"reasoning","domain":"cycle"},{"id":127,"prompt":"The requirement is a closed, approved inert-gas refrigeration loop that remains single phase and uses a work-producing expander with heat recuperation. Which cycle is the closest fit?","options":[{"id":"127-0","text":"Reverse Brayton.","feedback":"A gas compressor, recuperator and turbine expander are characteristic of a recuperated reverse Brayton refrigerator."},{"id":"127-1","text":"Simple steam Rankine.","feedback":"The conventional Rankine power loop has a different phase path and purpose."},{"id":"127-2","text":"Single-valve Linde–Hampson without an expander.","feedback":"The specified work-producing expander is absent from that simple JT description."},{"id":"127-3","text":"Conventional absorption using a solution generator.","feedback":"An absorption thermal-compressor loop is not the specified single-phase gas-expander architecture."}],"correct":"127-0","hint":"Identify how the low-temperature expansion is performed.","explanation":"A gas compressor, recuperator and turbine expander are characteristic of a recuperated reverse Brayton refrigerator.","trap":"","kind":"reasoning","graph":{"type":"cycle","labels":["Gas compressor","Heat rejection","Gas expander","Cold heat load"]},"domain":"cycle"},{"id":128,"prompt":"Two hypothetical LNG routes meet every technical and operability constraint. N₂ expansion uses 500 kW; SMR uses 300 kW and costs $250,000 more. Operation is 8000 h/year at $0.10/kWh. The sole financial rule is simple payback below 3 years. Which assessment follows?","options":[{"id":"128-0","text":"SMR meets the rule: about 1.56-year payback.","feedback":"Saving=(500−300)×8000×0.10=$160,000/year; payback=250,000/160,000=1.56 years."},{"id":"128-1","text":"SMR fails the rule: about 15.6-year payback.","feedback":"This is ten times the supplied economic result."},{"id":"128-2","text":"N₂ must win because the same product temperature means equal power.","feedback":"Equal product temperature does not imply equal irreversible cycle power."},{"id":"128-3","text":"SMR meets the rule because added capital is recovered in 0.156 years.","feedback":"This is ten times too short."}],"correct":"128-0","hint":"Use the stated vendor performance as hypothetical data, not universal cycle efficiency.","explanation":"Saving=(500−300)×8000×0.10=$160,000/year; payback=250,000/160,000=1.56 years.","trap":"","kind":"calculation","domain":"cycle"},{"id":129,"prompt":"For a particular LNG project, approved inert nitrogen is allowed but hydrocarbon refrigerant inventories are prohibited. All shortlisted routes can meet duty. Which shortlisted refrigerant route satisfies this stated constraint?","options":[{"id":"129-0","text":"Pure-N₂ turboexpander refrigeration.","feedback":"The approved nitrogen working fluid meets the stated refrigerant-inventory constraint; other requirements still need evaluation."},{"id":"129-1","text":"A methane/ethane/butane mixed-refrigerant loop.","feedback":"That mixture contains hydrocarbons, prohibited by the scenario."},{"id":"129-2","text":"A propane/ethylene/methane cascade.","feedback":"All three named refrigerants are hydrocarbons."},{"id":"129-3","text":"A propane-precooled hydrocarbon mixed-refrigerant loop.","feedback":"The precooler and mixed-refrigerant inventory include prohibited hydrocarbons."}],"correct":"129-0","hint":"Apply mandatory constraints before comparing nominal efficiency.","explanation":"The approved nitrogen working fluid meets the stated refrigerant-inventory constraint; other requirements still need evaluation.","trap":"","kind":"reasoning","domain":"cycle"},{"id":130,"prompt":"Which description best matches the SIMPLE classic Linde–Hampson liquefaction arrangement?","options":[{"id":"130-0","text":"Compression, heat rejection, recuperative cooling, JT throttling and phase separation.","feedback":"The returning cold stream precools high-pressure feed, and the final JT step can produce a liquid fraction at suitable states."},{"id":"130-1","text":"Gas compression, heating and a net power-producing turbine without a cold end.","feedback":"That describes a power-cycle direction rather than the classic JT liquefier."},{"id":"130-2","text":"Liquid-water pumping, boiling, steam expansion and condensation.","feedback":"That is a simple steam Rankine description."},{"id":"130-3","text":"An absorber and generator replacing the refrigeration gas circuit.","feedback":"An absorber/generator belongs to an absorption refrigeration concept."}],"correct":"130-0","hint":"Look for the recuperator and the type of final expansion.","explanation":"The returning cold stream precools high-pressure feed, and the final JT step can produce a liquid fraction at suitable states.","trap":"","kind":"reasoning","domain":"cycle"},{"id":131,"prompt":"What is a defining change in a classic Claude liquefaction concept relative to a simple Linde–Hampson concept?","options":[{"id":"131-0","text":"An expansion engine provides precooling while a final JT branch can still form liquid.","feedback":"Claude combines work-producing expansion for precooling with JT final expansion in its classic form."},{"id":"131-1","text":"Every throttle is eliminated and all feed must exit the turbine as liquid.","feedback":"The classic concept can retain final JT expansion and does not require all feed through a liquid-producing turbine."},{"id":"131-2","text":"All compression work is eliminated by a passive recuperator.","feedback":"Recuperation recovers cold between streams but does not eliminate required compression work."},{"id":"131-3","text":"The only addition is a larger storage tank after the same cycle.","feedback":"Storage alone does not create the expansion-engine precooling architecture."}],"correct":"131-0","hint":"Separate the expander branch from the final liquefaction branch.","explanation":"Claude combines work-producing expansion for precooling with JT final expansion in its classic form.","trap":"","kind":"reasoning","domain":"cycle"},{"id":132,"prompt":"A property model gives μJT=(∂T/∂p)h<0 throughout a modest throttle pressure drop. Under the usual isenthalpic assumptions, what temperature trend follows?","options":[{"id":"132-0","text":"Temperature increases as pressure decreases.","feedback":"dT=μJT dp; two negative factors give positive dT."},{"id":"132-1","text":"Temperature decreases as pressure decreases.","feedback":"That would follow from positive μJT for a pressure decrease."},{"id":"132-2","text":"Temperature stays fixed for every real fluid.","feedback":"Isenthalpic does not imply isothermal for a real fluid."},{"id":"132-3","text":"The entire stream must condense.","feedback":"The sign of μJT alone does not establish complete condensation."}],"correct":"132-0","hint":"Track the signs of both μJT and dp.","explanation":"dT=μJT dp; two negative factors give positive dT.","trap":"","kind":"reasoning","domain":"cycle"},{"id":133,"prompt":"A cryogenic turbine is explicitly qualified for dry gas only. A proposed outlet state lies inside the two-phase region. What is the appropriate design response?","options":[{"id":"133-0","text":"Revise state/split or hardware selection to respect the dry-gas limit.","feedback":"A supplier dry-gas limit requires a compatible outlet/path or appropriately qualified alternative."},{"id":"133-1","text":"Assume droplets are harmless because expansion recovers work.","feedback":"Work recovery does not remove erosion, performance or mechanical concerns."},{"id":"133-2","text":"Declare every turbine suitable for liquid production.","feedback":"Two-phase capability is equipment-specific, not universal."},{"id":"133-3","text":"Ignore the phase check because inlet gas was dry.","feedback":"A dry inlet can expand into a two-phase state."}],"correct":"133-0","hint":"Check the complete expansion path against the actual equipment envelope.","explanation":"A supplier dry-gas limit requires a compatible outlet/path or appropriately qualified alternative.","trap":"","kind":"reasoning","domain":"cycle"},{"id":134,"prompt":"Why can a cascade refrigeration architecture be useful for a very wide temperature range?","options":[{"id":"134-0","text":"Different stages/refrigerants can serve suitable temperature levels, at the cost of added equipment and interfaces.","feedback":"Temperature staging can distribute the lift and improve matching, while complexity and interfaces increase."},{"id":"134-1","text":"One compressor is guaranteed to operate at zero work across the entire range.","feedback":"A refrigeration temperature lift still requires energy input."},{"id":"134-2","text":"Each added stage necessarily lowers total installed cost.","feedback":"More stages can add capital and maintenance even when they improve performance."},{"id":"134-3","text":"It avoids all condenser heat rejection.","feedback":"Each stage transfers heat and work to a warmer stage or final heat sink."}],"correct":"134-0","hint":"Think about distributing the temperature lift, not making it disappear.","explanation":"Temperature staging can distribute the lift and improve matching, while complexity and interfaces increase.","trap":"","kind":"reasoning","domain":"cycle"},{"id":135,"prompt":"A mixed refrigerant's phase-change temperature glide better matches the natural-gas cooling curve. All else being considered, what is the thermodynamic opportunity?","options":[{"id":"135-0","text":"Reduce finite-temperature heat-transfer irreversibility, while checking pinch and equipment cost.","feedback":"Closer temperature matching can reduce exergy destruction, but pressure losses, pinch, area and operation still matter."},{"id":"135-1","text":"Guarantee the lowest lifecycle cost for every plant.","feedback":"Overall economics depend on more than thermodynamic matching."},{"id":"135-2","text":"Eliminate compression and external heat rejection.","feedback":"The cycle still needs energy input and a heat-rejection path."},{"id":"135-3","text":"Make methane purity independent of feed cleanup.","feedback":"Refrigeration matching is not feed purification."}],"correct":"135-0","hint":"A well-matched heat exchanger reduces avoidable temperature differences.","explanation":"Closer temperature matching can reduce exergy destruction, but pressure losses, pinch, area and operation still matter.","trap":"","kind":"reasoning","domain":"cycle"},{"id":136,"prompt":"In a recuperative cryogenic refrigerator, what does the returning low-pressure cold stream do in the recuperator?","options":[{"id":"136-0","text":"Precools the incoming high-pressure stream while warming itself.","feedback":"The recuperator transfers heat between separate streams, recovering cold internally."},{"id":"136-1","text":"Creates net refrigeration without any work or external temperature difference.","feedback":"Internal heat recovery does not by itself supply all net refrigeration."},{"id":"136-2","text":"Increases feed enthalpy so less compression is needed in every case.","feedback":"The intended cold-end recuperation precools the high-pressure flow."},{"id":"136-3","text":"Mixes directly with feed in every recuperator design.","feedback":"A recuperative heat exchanger can keep the high- and low-pressure circuits separate."}],"correct":"136-0","hint":"Follow energy on both sides of the exchanger.","explanation":"The recuperator transfers heat between separate streams, recovering cold internally.","trap":"","kind":"reasoning","domain":"cycle"},{"id":137,"prompt":"A heat-driven absorption chiller removes 1.0 MW with thermal COP=0.70. Ignore small pump work. Approximately what generator heat input and total ambient rejection follow?","options":[{"id":"137-0","text":"1.43 MW driving heat; 2.43 MW rejection.","feedback":"Qdrive=Qcold/COP=1/0.70=1.43 MW; overall rejection≈Qdrive+Qcold=2.43 MW."},{"id":"137-1","text":"0.70 MW driving heat; 1.70 MW rejection.","feedback":"This multiplies by COP instead of dividing."},{"id":"137-2","text":"1.43 MW driving heat; 1.00 MW rejection.","feedback":"Driving heat must also leave the overall chiller boundary."},{"id":"137-3","text":"0.30 MW driving heat; 1.30 MW rejection.","feedback":"1−COP is not the heat-input relation."}],"correct":"137-0","hint":"Use thermal-input COP, then close the whole-device energy balance.","explanation":"Qdrive=Qcold/COP=1/0.70=1.43 MW; overall rejection≈Qdrive+Qcold=2.43 MW.","trap":"","kind":"calculation","domain":"cycle"},{"id":138,"prompt":"Reversible refrigerators reject to 300 K and each provide 1 MW at a uniform cold-reservoir temperature. Approximately what minimum work is required at Tc=112 K and Tc=280 K?","options":[{"id":"138-0","text":"About 1.68 MW at 112 K; 0.0714 MW at 280 K.","feedback":"Wmin=Qcold(Th/Tc−1): 300/112−1=1.679; 300/280−1=0.07143."},{"id":"138-1","text":"About 0.0714 MW at 112 K; 1.68 MW at 280 K.","feedback":"This reverses the larger and smaller temperature lifts."},{"id":"138-2","text":"About 0.596 MW at 112 K; 14 MW at 280 K.","feedback":"0.596 and 14 are the respective COP values, not work for 1 MW duty."},{"id":"138-3","text":"Exactly 1 MW at both temperatures.","feedback":"Fixed cold duty does not fix work when temperature lift changes."}],"correct":"138-0","hint":"Convert the reversible COP to work per unit cold duty.","explanation":"Wmin=Qcold(Th/Tc−1): 300/112−1=1.679; 300/280−1=0.07143.","trap":"","kind":"calculation","domain":"cycle"},{"id":139,"prompt":"Why is compression work in an idealized Rankine feedwater pump often small relative to gas compression over a comparable pressure increase?","options":[{"id":"139-0","text":"The pump compresses a low-specific-volume liquid; work is approximately vΔp.","feedback":"The small liquid specific volume makes vΔp comparatively modest; work is not zero."},{"id":"139-1","text":"Liquid pressure cannot increase, so pump work is exactly zero.","feedback":"Liquids are nearly incompressible but can still be raised to higher pressure with work."},{"id":"139-2","text":"The pump produces work because the water is cold.","feedback":"A feed pump normally consumes work."},{"id":"139-3","text":"Water's latent heat cancels every pump loss.","feedback":"Latent heat does not cancel hydraulic input or inefficiency."}],"correct":"139-0","hint":"Compare specific volume in the compression-work integral.","explanation":"The small liquid specific volume makes vΔp comparatively modest; work is not zero.","trap":"","kind":"reasoning","domain":"cycle"},{"id":140,"prompt":"A proposed passive Brayton recuperator would preheat compressor discharge at 500 K using turbine exhaust at 450 K. What is the correct assessment for that intended heat-flow direction?","options":[{"id":"140-0","text":"It cannot passively preheat the 500 K stream using the 450 K exhaust.","feedback":"The proposed hot source is colder than the stream to be preheated; this intended passive transfer is infeasible."},{"id":"140-1","text":"It must work because a recuperator always raises cycle efficiency.","feedback":"Recuperation benefit depends on suitable temperature ordering and losses."},{"id":"140-2","text":"It heats both streams without another input.","feedback":"A passive two-stream heat exchanger does not add heat to both streams."},{"id":"140-3","text":"It guarantees a net-work increase equal to turbine power.","feedback":"The supplied temperatures do not support the proposed preheating or that work claim."}],"correct":"140-0","hint":"Check temperature ordering before selecting a heat-recovery device.","explanation":"The proposed hot source is colder than the stream to be preheated; this intended passive transfer is infeasible.","trap":"","kind":"reasoning","domain":"cycle"},{"id":141,"prompt":"A solid rectangular beam keeps the same width but doubles its vertical depth. Under the same bending moment and span/load, how do maximum bending stress and elastic deflection scale?","options":[{"id":"141-0","text":"Stress ×1/4; deflection ×1/8.","feedback":"I∝h³ and section modulus I/c∝h², so stress scales as h⁻² and deflection as h⁻³."},{"id":"141-1","text":"Stress ×1/8; deflection ×1/4.","feedback":"This reverses section-modulus and second-moment dependencies."},{"id":"141-2","text":"Stress ×1/2; deflection ×1/2.","feedback":"Depth affects both properties by more than a linear power."},{"id":"141-3","text":"Stress unchanged; deflection ×1/8.","feedback":"Moving the outer fiber and changing I also changes maximum stress."}],"correct":"141-0","hint":"For stress use section modulus; for deflection use I.","explanation":"I∝h³ and section modulus I/c∝h², so stress scales as h⁻² and deflection as h⁻³.","trap":"","kind":"calculation","domain":"structure"},{"id":142,"prompt":"A circular thin-wall pressure vessel is adequate against nominal membrane yield. Which additional load can still threaten a slender pipe support during cooldown?","options":[{"id":"142-0","text":"Thermal restraint loads, pressure thrust and buckling of the support.","feedback":"The support has its own load path and failure modes beyond vessel membrane pressure stress."},{"id":"142-1","text":"No additional load, because the vessel passed a hoop check.","feedback":"A vessel membrane check does not qualify supports or connections."},{"id":"142-2","text":"Only liquid density; geometry and restraint cannot matter.","feedback":"Geometry and restraint strongly influence mechanical loads and stability."},{"id":"142-3","text":"Only temperature-independent room-temperature yield strength.","feedback":"Low-temperature properties and actual loading still matter."}],"correct":"142-0","hint":"Draw separate free bodies for pressure boundary and support.","explanation":"The support has its own load path and failure modes beyond vessel membrane pressure stress.","trap":"","kind":"reasoning","domain":"structure"},{"id":143,"prompt":"An initially straight slender rod is fully restrained and heated. Before considering detailed stresses, which paired mechanism is consistent with first principles?","options":[{"id":"143-0","text":"Compressive thermal stress and possible buckling.","feedback":"Restraints oppose free expansion with compression, which can destabilize a slender member."},{"id":"143-1","text":"Tensile thermal stress and no possible instability.","feedback":"Prevented heating expansion produces compression rather than tension."},{"id":"143-2","text":"No stress because thermal strain is not mechanical strain.","feedback":"Preventing thermal strain generates mechanical reaction strain and stress."},{"id":"143-3","text":"A stress sign fixed only by yield strength.","feedback":"Load and restraint determine sign, not yield strength."}],"correct":"143-0","hint":"Ask what reaction is needed to stop free expansion.","explanation":"Restraints oppose free expansion with compression, which can destabilize a slender member.","trap":"","kind":"reasoning","domain":"structure"},{"id":144,"prompt":"A cryogenic support must carry equipment while limiting conductive heat leak. Which statement captures the design tradeoff?","options":[{"id":"144-0","text":"Reducing A/L cuts heat conduction but can reduce stiffness or stability.","feedback":"Conduction scales with kA/L, while strength, stiffness and buckling impose competing geometry requirements."},{"id":"144-1","text":"Reducing area always improves both heat leak and load capacity.","feedback":"A smaller cross-section generally carries less load or deflects more."},{"id":"144-2","text":"Increasing conductivity always reduces heat leak at fixed geometry.","feedback":"Higher k increases conduction under the stated boundary temperatures."},{"id":"144-3","text":"Adding fully rigid supports eliminates every thermal-load concern.","feedback":"Rigid supports can add heat bridges and thermal restraint."}],"correct":"144-0","hint":"Evaluate the same geometry in both thermal and mechanical models.","explanation":"Conduction scales with kA/L, while strength, stiffness and buckling impose competing geometry requirements.","trap":"","kind":"reasoning","domain":"structure"},{"id":145,"prompt":"A ductile point has plane stress σx=100 MPa, σy=0 and τxy=50 MPa. Use von Mises σeq=√(σx²−σxσy+σy²+3τxy²). With yield 250 MPa, approximately what are equivalent stress and simple yield factor?","options":[{"id":"145-0","text":"132 MPa; factor 1.89.","feedback":"σeq=√(100²+3×50²)=132.3 MPa; 250/132.3=1.89."},{"id":"145-1","text":"150 MPa; factor 1.67.","feedback":"Adding normal and shear stress directly is not the supplied criterion."},{"id":"145-2","text":"100 MPa; factor 2.50.","feedback":"This omits the shear contribution."},{"id":"145-3","text":"50 MPa; factor 5.00.","feedback":"This omits normal stress and the combined criterion."}],"correct":"145-0","hint":"Combine the stress components before dividing yield by equivalent stress.","explanation":"σeq=√(100²+3×50²)=132.3 MPa; 250/132.3=1.89.","trap":"","kind":"calculation","domain":"structure"},{"id":146,"prompt":"A bracket stays below yield but deflects enough to misalign a pump coupling. What does that show?","options":[{"id":"146-0","text":"The design can pass strength and still fail serviceability or alignment.","feedback":"Stiffness and interface displacement are separate acceptance requirements."},{"id":"146-1","text":"Any below-yield bracket automatically meets alignment limits.","feedback":"An elastic displacement can still exceed an operating tolerance."},{"id":"146-2","text":"Yield strength alone sets elastic deflection.","feedback":"Elastic deflection depends on modulus, geometry, loading and restraint."},{"id":"146-3","text":"A higher factor against yield guarantees smaller elastic displacement.","feedback":"Changing yield margin does not necessarily change EI or support compliance."}],"correct":"146-0","hint":"Separate an allowable displacement from an allowable stress.","explanation":"Stiffness and interface displacement are separate acceptance requirements.","trap":"","kind":"reasoning","domain":"structure"},{"id":147,"prompt":"For the same ideal Euler column, pinned-pinned effective-length factor is K=1 and fixed-fixed factor is K=0.5. What ideal critical-load ratio is predicted for fixed-fixed versus pinned-pinned?","options":[{"id":"147-0","text":"4","feedback":"Pcr∝1/(KL)², so (1/0.5)²=4."},{"id":"147-1","text":"2","feedback":"This omits the square on effective length."},{"id":"147-2","text":"1/2","feedback":"Greater ideal end restraint raises rather than halves Pcr."},{"id":"147-3","text":"1/4","feedback":"This reverses the ratio."}],"correct":"147-0","hint":"Square the effective-length factor ratio; actual end fixity must be justified.","explanation":"Pcr∝1/(KL)², so (1/0.5)²=4.","trap":"","kind":"calculation","domain":"structure"},{"id":148,"prompt":"For a solid circular elastic shaft at unchanged torque and length, maximum torsional stress scales as d⁻³ and twist as d⁻⁴. Increasing diameter 20% gives approximately what fractions?","options":[{"id":"148-0","text":"Stress 0.579; twist 0.482.","feedback":"1/1.2³≈0.579 and 1/1.2⁴≈0.482."},{"id":"148-1","text":"Stress 0.482; twist 0.579.","feedback":"This reverses the supplied exponents."},{"id":"148-2","text":"Stress 0.833; twist 0.833.","feedback":"These are the inverse-first-power diameter fractions."},{"id":"148-3","text":"Stress 1.728; twist 2.074.","feedback":"Those are the denominator increases, not the resulting response fractions."}],"correct":"148-0","hint":"Apply each supplied inverse power to the same diameter ratio.","explanation":"1/1.2³≈0.579 and 1/1.2⁴≈0.482.","trap":"","kind":"calculation","domain":"structure"},{"id":149,"prompt":"A welded support sees many load reversals, all nominally below yield. Which conclusion is defensible?","options":[{"id":"149-0","text":"A fatigue assessment can still be needed, including stress range, weld detail and cycle history.","feedback":"Repeated elastic cycling can still cause fatigue, with detail and stress concentration important."},{"id":"149-1","text":"Below-yield nominal stress proves unlimited life for every weld.","feedback":"No such universal unlimited-life conclusion follows."},{"id":"149-2","text":"Static yield factor alone determines the exact cycles to failure.","feedback":"Fatigue depends on cycling and detail, not only monotonic yield."},{"id":"149-3","text":"Thermal cycles cannot create fatigue if the external force is constant.","feedback":"Thermal restraint and differential movement can create stress cycles."}],"correct":"149-0","hint":"Ask how the stress varies over time at the critical detail.","explanation":"Repeated elastic cycling can still cause fatigue, with detail and stress concentration important.","trap":"","kind":"reasoning","domain":"structure"},{"id":150,"prompt":"A new rigid pipe support reduces gravity sag but cold commissioning shows large nozzle loads. What is the most appropriate first-principles investigation?","options":[{"id":"150-0","text":"Check the changed thermal load path, anchor/guide freedom, contraction and measured movements.","feedback":"A stiffer gravity arrangement can block contraction and redirect load into equipment nozzles."},{"id":"150-1","text":"Add more fixed supports immediately to eliminate every movement.","feedback":"More restraint can worsen the contraction loads."},{"id":"150-2","text":"Assume gravity capacity proves acceptable thermal nozzle loads.","feedback":"Gravity and thermal load cases have different forcing and boundary conditions."},{"id":"150-3","text":"Treat the cold displacement as impossible because steel is strong.","feedback":"Finite expansion/contraction and support stiffness can create large loads even without yielding."}],"correct":"150-0","hint":"Compare the free cold shape with the shape the new restraints permit.","explanation":"A stiffer gravity arrangement can block contraction and redirect load into equipment nozzles.","trap":"","kind":"reasoning","domain":"structure"}];
